/* Drumul spre Romana — Dialogues and reading passages.
 *
 * Pure data. Extracted verbatim from index.html; no logic, no dependencies,
 * nothing here references anything else. Loaded as a classic script before the
 * application, so each name below is a global.
 *
 * These files are split by DOCUMENT ORDER, not by theme, and must stay in that
 * order: tools/_sources.py concatenates them to rebuild the original text so
 * the region markers in check_content.py, check_reuse.py, extract_strings.py
 * and verify_verbs.py keep slicing the same spans. Reordering them, or moving a
 * dataset between files, will silently change what those tools scan.
 */
"use strict";

/* ===================== DIALOGUES (lesson context stages) ===================== */
var DIALOGUES = [
 {id:"d_u1l1", title:"La facultate", titleEn:"At the university", level:"a1_1",
  lines:[
   {speaker:"Mihai", ro:"Bună! Eu sunt Mihai.", en:"Hi! I'm Mihai."},
   {speaker:"Ana", ro:"Bună, Mihai! Eu sunt Ana. Ce mai faci?", en:"Hi, Mihai! I'm Ana. How are you?"},
   {speaker:"Mihai", ro:"Bine, mulțumesc. Și tu?", en:"Fine, thanks. And you?"},
   {speaker:"Ana", ro:"Bine, mulțumesc! La revedere, pe curând!", en:"Fine, thanks! Goodbye, see you soon!"},
   {speaker:"Mihai", ro:"Pe curând!", en:"See you soon!"}
  ]},
 {id:"d_u1l2", title:"Cine ești?", titleEn:"Who are you?", level:"a1_1",
  lines:[
   {speaker:"Recepționer", ro:"Bună ziua! Cum vă numiți?", en:"Good day! What's your name? (formal)"},
   {speaker:"Sarah", ro:"Bună ziua! Numele meu este Sarah. Sunt studentă.", en:"Good day! My name is Sarah. I'm a student."},
   {speaker:"Recepționer", ro:"Sunteți din Anglia?", en:"Are you from England?"},
   {speaker:"Sarah", ro:"Nu, nu sunt din Anglia. Sunt din Statele Unite. Dar vorbesc puțină română!", en:"No, I'm not from England. I'm from the United States. But I speak a little Romanian!"},
   {speaker:"Recepționer", ro:"Foarte bine! Bine ați venit în România.", en:"Very good! Welcome to Romania."}
  ]},
 {id:"d_u1l3", title:"De unde sunteți?", titleEn:"Where are you from?", level:"a1_1",
  lines:[
   {speaker:"Elena", ro:"Salut! Eu sunt Elena, sunt din România. Tu de unde ești?", en:"Hi! I'm Elena, I'm from Romania. Where are you from?"},
   {speaker:"Tom", ro:"Eu sunt Tom. Sunt american, din New York.", en:"I'm Tom. I'm American, from New York."},
   {speaker:"Elena", ro:"Și el, cine este?", en:"And him, who is he?"},
   {speaker:"Tom", ro:"El este Lukas. Este german, din Berlin. Vorbește și engleză, și română.", en:"He's Lukas. He's German, from Berlin. He speaks both English and Romanian."},
   {speaker:"Elena", ro:"Ce interesant! Bine ați venit la Cluj!", en:"How interesting! Welcome to Cluj!"}
  ]},
 {id:"d_u2l1", title:"Aceasta este familia mea", titleEn:"This is my family", level:"a1_1",
  lines:[
   {speaker:"Ioana", ro:"Uite o poză cu familia mea. Aceasta este mama, iar acesta este tatăl meu.", en:"Here's a photo of my family. This is my mom, and this is my dad."},
   {speaker:"Radu", ro:"Ce familie frumoasă! Ai frați sau surori?", en:"What a beautiful family! Do you have brothers or sisters?"},
   {speaker:"Ioana", ro:"Da, am un frate și o soră. El are treizeci de ani, iar ea are douăzeci și cinci.", en:"Yes, I have a brother and a sister. He is thirty years old, and she is twenty-five."},
   {speaker:"Radu", ro:"Și bunicii tăi locuiesc tot la Cluj?", en:"And do your grandparents also live in Cluj?"},
   {speaker:"Ioana", ro:"Nu, bunicii mei locuiesc la țară, într-un sat mic.", en:"No, my grandparents live in the countryside, in a small village."}
  ]},
 {id:"d_u2l2", title:"Cum arată el?", titleEn:"What does he look like?", level:"a1_1",
  lines:[
   {speaker:"Diana", ro:"Îl cunoști pe noul coleg?", en:"Do you know the new colleague?"},
   {speaker:"Vlad", ro:"Nu încă. Cum arată?", en:"Not yet. What does he look like?"},
   {speaker:"Diana", ro:"Este înalt, are părul negru și ochii verzi. E foarte simpatic.", en:"He's tall, has black hair and green eyes. He's very nice."},
   {speaker:"Vlad", ro:"Pare drăguț. Câți ani are?", en:"He seems nice. How old is he?"},
   {speaker:"Diana", ro:"Cred că are vreo treizeci de ani.", en:"I think he's about thirty years old."}
  ]},
 {id:"d_u3l1", title:"Cât e ceasul?", titleEn:"What time is it?", level:"a1_1",
  lines:[
   {speaker:"Paul", ro:"Scuze, cât e ceasul?", en:"Excuse me, what time is it?"},
   {speaker:"Cristina", ro:"Este ora nouă și jumătate.", en:"It's half past nine."},
   {speaker:"Paul", ro:"Mulțumesc! La ce oră începe filmul?", en:"Thanks! What time does the movie start?"},
   {speaker:"Cristina", ro:"Începe la ora zece fix. Mai avem treizeci de minute.", en:"It starts at ten o'clock sharp. We still have thirty minutes."}
  ]},
 {id:"d_u3l2", title:"O zi obișnuită", titleEn:"An ordinary day", level:"a1_1",
  lines:[
   {speaker:"Bogdan", ro:"Cum arată o zi obișnuită pentru tine?", en:"What does an ordinary day look like for you?"},
   {speaker:"Laura", ro:"Mă trezesc la șapte, beau o cafea și merg la serviciu.", en:"I wake up at seven, drink a coffee, and go to work."},
   {speaker:"Bogdan", ro:"La ce oră termini munca?", en:"What time do you finish work?"},
   {speaker:"Laura", ro:"De obicei termin la cinci. Seara citesc sau merg la sală.", en:"I usually finish at five. In the evening I read or go to the gym."}
  ]},
 {id:"d_u4l1", title:"La cafenea", titleEn:"At the café", level:"a1_1",
  lines:[
   {speaker:"Chelner", ro:"Bună ziua! Ce doriți?", en:"Good day! What would you like?"},
   {speaker:"Client", ro:"Bună ziua! Aș dori o cafea cu lapte, vă rog.", en:"Good day! I'd like a coffee with milk, please."},
   {speaker:"Chelner", ro:"Sigur. Doriți și ceva de mâncare?", en:"Certainly. Would you like something to eat as well?"},
   {speaker:"Client", ro:"Da, un croasant, vă rog. Cât costă în total?", en:"Yes, a croissant, please. How much is it altogether?"},
   {speaker:"Chelner", ro:"Optsprezece lei, vă rog.", en:"Eighteen lei, please."},
   {speaker:"Client", ro:"Poftiți. Mulțumesc!", en:"Here you are. Thank you!"}
  ]},
 {id:"d_u4l2", title:"La restaurant", titleEn:"At the restaurant", level:"a1_1",
  lines:[
   {speaker:"Chelneriță", ro:"Ați ales? Ce luați ca fel principal?", en:"Have you chosen? What are you having as a main course?"},
   {speaker:"Ana", ro:"Îmi place peștele. Iau pește cu legume, vă rog.", en:"I like fish. I'll have fish with vegetables, please."},
   {speaker:"Dan", ro:"Pentru mine o ciorbă și apoi sarmale.", en:"For me a sour soup and then sarmale."},
   {speaker:"Chelneriță", ro:"Și de băut?", en:"And to drink?"},
   {speaker:"Dan", ro:"O bere, vă rog. Ana, tu ce bei?", en:"A beer, please. Ana, what are you drinking?"},
   {speaker:"Ana", ro:"Doar apă plată, mulțumesc. Nu-mi place berea.", en:"Just still water, thanks. I don't like beer."}
  ]},
 {id:"d_u5l1", title:"Cât costă?", titleEn:"How much is it?", level:"a1_1",
  lines:[
   {speaker:"Vânzătoare", ro:"Bună ziua! Cu ce vă pot ajuta?", en:"Good day! How can I help you?"},
   {speaker:"Client", ro:"Caut o cămașă albă. Cât costă aceasta?", en:"I'm looking for a white shirt. How much is this one?"},
   {speaker:"Vânzătoare", ro:"Costă o sută douăzeci de lei.", en:"It costs one hundred and twenty lei."},
   {speaker:"Client", ro:"Este cam scumpă. Aveți ceva mai ieftin?", en:"That's rather expensive. Do you have something cheaper?"},
   {speaker:"Vânzătoare", ro:"Da, aceasta costă optzeci de lei. Ce mărime purtați?", en:"Yes, this one costs eighty lei. What size do you wear?"},
   {speaker:"Client", ro:"Mărimea M. Pot să o probez?", en:"Size M. Can I try it on?"}
  ]},
 {id:"d_u6l1", title:"Scuzați-mă, unde este gara?", titleEn:"Excuse me, where is the station?", level:"a1_1",
  lines:[
   {speaker:"Turist", ro:"Scuzați-mă, unde este gara, vă rog?", en:"Excuse me, where is the train station, please?"},
   {speaker:"Trecător", ro:"Mergeți drept înainte două străzi, apoi la stânga.", en:"Go straight ahead for two streets, then left."},
   {speaker:"Turist", ro:"Este departe de aici?", en:"Is it far from here?"},
   {speaker:"Trecător", ro:"Nu, sunt zece minute pe jos. Gara este vizavi de un parc mare.", en:"No, it's ten minutes on foot. The station is opposite a big park."},
   {speaker:"Turist", ro:"Mulțumesc mult pentru ajutor!", en:"Thank you very much for your help!"},
   {speaker:"Trecător", ro:"Cu plăcere! Drum bun!", en:"You're welcome! Have a good trip!"}
  ]},
 {id:"d_u6l2", title:"Cu ce ajung în centru?", titleEn:"How do I get to the center?", level:"a1_1",
  lines:[
   {speaker:"Maria", ro:"Cu ce ajung în centru de aici?", en:"How do I get to the center from here?"},
   {speaker:"Local", ro:"Puteți lua autobuzul 105 sau metroul.", en:"You can take bus 105 or the subway."},
   {speaker:"Maria", ro:"Care este mai rapid?", en:"Which is faster?"},
   {speaker:"Local", ro:"Metroul, sigur. Autobuzul stă mult în trafic.", en:"The subway, definitely. The bus sits in traffic a lot."},
   {speaker:"Maria", ro:"Unde cumpăr un bilet?", en:"Where do I buy a ticket?"},
   {speaker:"Local", ro:"La casa de bilete, chiar lângă intrare.", en:"At the ticket office, right next to the entrance."}
  ]},
 {id:"d_u7l1", title:"Un apartament de închiriat", titleEn:"A flat to rent", level:"a1_1",
  lines:[
   {speaker:"Agent", ro:"Bună ziua! Acesta este apartamentul. Are două camere.", en:"Good day! This is the flat. It has two rooms."},
   {speaker:"Client", ro:"Este luminos. Unde este bucătăria?", en:"It's bright. Where is the kitchen?"},
   {speaker:"Agent", ro:"Bucătăria este la stânga, lângă baie. Dormitorul este la dreapta.", en:"The kitchen is on the left, next to the bathroom. The bedroom is on the right."},
   {speaker:"Client", ro:"Are balcon?", en:"Does it have a balcony?"},
   {speaker:"Agent", ro:"Da, balconul este în sufragerie și dă spre parc.", en:"Yes, the balcony is off the living room and looks onto the park."},
   {speaker:"Client", ro:"Îmi place. Cât este chiria?", en:"I like it. How much is the rent?"},
   {speaker:"Agent", ro:"Patru sute cincizeci de euro pe lună, plus întreținerea.", en:"Four hundred and fifty euros a month, plus maintenance."}
  ]},
 {id:"d_u8l1", title:"Cum e vremea?", titleEn:"What's the weather like?", level:"a1_1",
  lines:[
   {speaker:"Ana", ro:"Cum este vremea afară?", en:"What's the weather like outside?"},
   {speaker:"Mihai", ro:"Plouă și bate vântul. Ia o umbrelă!", en:"It's raining and windy. Take an umbrella!"},
   {speaker:"Ana", ro:"Câte grade sunt?", en:"How many degrees is it?"},
   {speaker:"Mihai", ro:"Doar zece grade. E cam frig pentru mai.", en:"Only ten degrees. It's rather cold for May."},
   {speaker:"Ana", ro:"Sper că mâine va fi soare.", en:"I hope it'll be sunny tomorrow."},
   {speaker:"Mihai", ro:"Da, se anunță frumos la sfârșitul săptămânii.", en:"Yes, they're forecasting nice weather at the end of the week."}
  ]},
 {id:"d_a12u1", title:"Cu ce te ocupi?", titleEn:"What do you do?", level:"a1_2",
  lines:[
   {speaker:"Andrei", ro:"Tu cu ce te ocupi?", en:"What do you do (for a living)?"},
   {speaker:"Elena", ro:"Sunt programatoare la o firmă din centru. Dar tu?", en:"I'm a programmer at a company downtown. And you?"},
   {speaker:"Andrei", ro:"Eu sunt medic. Lucrez la spitalul de lângă parc.", en:"I'm a doctor. I work at the hospital near the park."},
   {speaker:"Elena", ro:"Ai un program greu?", en:"Do you have a hard schedule?"},
   {speaker:"Andrei", ro:"Uneori. De obicei încep la opt și termin la șase, dar rar plec la timp.", en:"Sometimes. I usually start at eight and finish at six, but I rarely leave on time."},
   {speaker:"Elena", ro:"Înțeleg. Eu am noroc — nu lucrez niciodată în weekend.", en:"I understand. I'm lucky — I never work at the weekend."}
  ]},
 {id:"d_a12u2", title:"Ce faci în timpul liber?", titleEn:"What do you do in your free time?", level:"a1_2",
  lines:[
   {speaker:"Maria", ro:"Ce faci de obicei în timpul liber?", en:"What do you usually do in your free time?"},
   {speaker:"Radu", ro:"Îmi place să citesc și să gătesc. Și joc fotbal sâmbăta.", en:"I like reading and cooking. And I play football on Saturdays."},
   {speaker:"Maria", ro:"Eu nu fac sport aproape deloc. Prefer să mă uit la filme.", en:"I hardly do any sport. I prefer watching films."},
   {speaker:"Radu", ro:"Ce filme îți plac?", en:"What films do you like?"},
   {speaker:"Maria", ro:"Îmi plac comediile. Nu-mi plac deloc filmele de groază.", en:"I like comedies. I don't like horror films at all."},
   {speaker:"Radu", ro:"Atunci mergem la o comedie weekendul viitor?", en:"Then shall we go to a comedy next weekend?"}
  ]},
 {id:"d_a12u3", title:"O programare la medic", titleEn:"A doctor's appointment", level:"a1_2",
  lines:[
   {speaker:"Recepție", ro:"Alo, cabinetul doctorului Ionescu, bună ziua!", en:"Hello, Doctor Ionescu's practice, good day!"},
   {speaker:"Pacient", ro:"Bună ziua! Aș vrea să fac o programare, vă rog.", en:"Good day! I'd like to make an appointment, please."},
   {speaker:"Recepție", ro:"Sigur. Când sunteți liber?", en:"Certainly. When are you free?"},
   {speaker:"Pacient", ro:"Joi sau vineri, dacă se poate. Joi sunt ocupat dimineața.", en:"Thursday or Friday, if possible. On Thursday I'm busy in the morning."},
   {speaker:"Recepție", ro:"Avem loc vineri, pe 14 martie, la ora unsprezece.", en:"We have a slot on Friday, the 14th of March, at eleven o'clock."},
   {speaker:"Pacient", ro:"Perfect. Vă mulțumesc mult!", en:"Perfect. Thank you very much!"}
  ]},
 {id:"d_a12u4", title:"La farmacie", titleEn:"At the pharmacy", level:"a1_2",
  lines:[
   {speaker:"Farmacist", ro:"Bună ziua! Cu ce vă pot ajuta?", en:"Good day! How can I help you?"},
   {speaker:"Client", ro:"Bună ziua. Mă doare gâtul de două zile și cred că am febră.", en:"Good day. My throat has hurt for two days and I think I have a fever."},
   {speaker:"Farmacist", ro:"Aveți rețetă de la medic?", en:"Do you have a prescription from the doctor?"},
   {speaker:"Client", ro:"Nu, încă nu am fost la medic.", en:"No, I haven't been to the doctor yet."},
   {speaker:"Farmacist", ro:"Vă dau ceva pentru gât. Dacă febra nu scade în două zile, mergeți la medic.", en:"I'll give you something for your throat. If the fever doesn't go down in two days, go to the doctor."},
   {speaker:"Client", ro:"Mulțumesc mult. Cât costă?", en:"Thank you very much. How much is it?"}
  ]},
 {id:"d_a12u5", title:"La casa de bilete", titleEn:"At the ticket office", level:"a1_2",
  lines:[
   {speaker:"Călător", ro:"Bună ziua. Un bilet până la Brașov, vă rog.", en:"Good day. One ticket to Brașov, please."},
   {speaker:"Casier", ro:"Dus sau dus-întors?", en:"One way or return?"},
   {speaker:"Călător", ro:"Dus-întors, mă întorc duminică.", en:"Return, I'm coming back on Sunday."},
   {speaker:"Casier", ro:"Trenul de la ora nouă are un loc liber la clasa a doua.", en:"The nine o'clock train has a free seat in second class."},
   {speaker:"Călător", ro:"Perfect. De la ce peron pleacă?", en:"Perfect. Which platform does it leave from?"},
   {speaker:"Casier", ro:"De la peronul patru. Atenție, are zece minute întârziere.", en:"From platform four. Careful, it has a ten-minute delay."}
  ]},
 {id:"d_a12u6", title:"O invitație", titleEn:"An invitation", level:"a1_2",
  lines:[
   {speaker:"Ana", ro:"Sâmbătă este ziua mea de naștere. Vii la petrecere?", en:"Saturday is my birthday. Are you coming to the party?"},
   {speaker:"Mihai", ro:"Sigur că vin! La ce oră începe?", en:"Of course I'm coming! What time does it start?"},
   {speaker:"Ana", ro:"Pe la șapte, la mine acasă.", en:"Around seven, at my place."},
   {speaker:"Mihai", ro:"Vine și Radu?", en:"Is Radu coming too?"},
   {speaker:"Ana", ro:"Din păcate nu poate, este plecat din oraș.", en:"Unfortunately he can't, he's out of town."},
   {speaker:"Mihai", ro:"Păcat. Atunci ne vedem sâmbătă — aduc eu ceva de băut.", en:"Shame. See you Saturday then — I'll bring something to drink."}
  ]},
 {id:"d_civ_interviu", title:"La interviu", titleEn:"At the interview", level:"civic",
  lines:[
   {speaker:"Funcționar", ro:"Bună ziua. Vă rog să vă prezentați.", en:"Good day. Please introduce yourself."},
   {speaker:"Solicitant", ro:"Bună ziua. Mă numesc Andrei Popa, am treizeci și patru de ani și locuiesc în Chișinău.", en:"Good day. My name is Andrei Popa, I am thirty-four years old and I live in Chișinău."},
   {speaker:"Funcționar", ro:"De ce doriți să redobândiți cetățenia română?", en:"Why do you wish to restore Romanian citizenship?"},
   {speaker:"Solicitant", ro:"Bunicii mei s-au născut în România. Vreau să păstrez legătura cu țara și cu limba lor.", en:"My grandparents were born in Romania. I want to keep the connection with their country and language."},
   {speaker:"Funcționar", ro:"Care este capitala României și care este ziua națională?", en:"What is the capital of Romania and what is the national day?"},
   {speaker:"Solicitant", ro:"Capitala este București, iar ziua națională este 1 decembrie.", en:"The capital is Bucharest, and the national day is 1 December."},
   {speaker:"Funcționar", ro:"Puteți să spuneți jurământul de credință?", en:"Can you say the oath of allegiance?"},
   {speaker:"Solicitant", ro:"Da. Jur să fiu devotat patriei și poporului român, să apăr drepturile și interesele naționale, să respect Constituția și legile României.", en:"Yes. I swear to be devoted to the homeland and the Romanian people, to defend the national rights and interests, to respect the Constitution and the laws of Romania."}
  ]},
 {id:"d_a2u1", title:"Weekendul trecut", titleEn:"Last weekend", level:"a2_1",
  lines:[
   {speaker:"Sorin", ro:"Ce ai făcut în weekend?", en:"What did you do on the weekend?"},
   {speaker:"Maria", ro:"Sâmbătă am mers la munte cu niște prieteni. Am mâncat la un restaurant tradițional și am făcut o drumeție.", en:"On Saturday I went to the mountains with some friends. We ate at a traditional restaurant and went hiking."},
   {speaker:"Sorin", ro:"Sună minunat! Eu am stat acasă și am citit o carte.", en:"Sounds wonderful! I stayed home and read a book."},
   {speaker:"Maria", ro:"Duminică ne-am întâlnit cu familia și am vizitat un muzeu nou din centru.", en:"On Sunday we met up with family and visited a new museum downtown."}
  ]},
 {id:"d_a2u2", title:"Ce planuri ai?", titleEn:"What are your plans?", level:"a2_1",
  lines:[
   {speaker:"Irina", ro:"Ce planuri ai pentru vara asta?", en:"What plans do you have for this summer?"},
   {speaker:"Cătălin", ro:"O să merg două săptămâni în Grecia. Am rezervat deja biletele.", en:"I'm going to Greece for two weeks. I've already booked the tickets."},
   {speaker:"Irina", ro:"Ce bine! Eu încă nu știu. Trebuie să vorbesc cu șeful despre concediu.", en:"How nice! I still don't know. I have to talk to my boss about the leave."},
   {speaker:"Cătălin", ro:"Ar trebui să te decizi repede, altfel se scumpesc biletele.", en:"You should decide quickly, otherwise the tickets get more expensive."},
   {speaker:"Irina", ro:"Ai dreptate. Sper să rezolv până vineri.", en:"You're right. I hope to sort it out by Friday."},
   {speaker:"Cătălin", ro:"Dacă vrei, îți trimit linkul agenției mele.", en:"If you like, I'll send you my agency's link."}
  ]},
 {id:"d_a2u3", title:"La recepția hotelului", titleEn:"At the hotel reception", level:"a2_1",
  lines:[
   {speaker:"Recepționer", ro:"Bună ziua! Aveți o rezervare?", en:"Good day! Do you have a reservation?"},
   {speaker:"Client", ro:"Da, pe numele Ionescu. O cameră dublă pentru trei nopți.", en:"Yes, under the name Ionescu. A double room for three nights."},
   {speaker:"Recepționer", ro:"Am găsit-o. Camera 214, la etajul doi. Poftiți cheia.", en:"I've found it. Room 214, on the second floor. Here's the key."},
   {speaker:"Client", ro:"Mulțumesc. Micul dejun este inclus?", en:"Thank you. Is breakfast included?"},
   {speaker:"Recepționer", ro:"Da, îl serviți între șapte și zece, la parter.", en:"Yes, you have it between seven and ten, on the ground floor."},
   {speaker:"Client", ro:"Perfect. Și la ce oră trebuie să eliberăm camera?", en:"Perfect. And what time do we have to check out?"},
   {speaker:"Recepționer", ro:"Până la ora douăsprezece. Vă doresc un sejur plăcut!", en:"By twelve o'clock. I wish you a pleasant stay!"}
  ]},
 {id:"d_a2u4", title:"La cabinetul medical", titleEn:"At the doctor's surgery", level:"a2_1",
  lines:[
   {speaker:"Medic", ro:"Bună ziua. Spuneți-mi, ce vă supără?", en:"Good day. Tell me, what's bothering you?"},
   {speaker:"Pacient", ro:"Tușesc de o săptămână și mă doare gâtul. Cred că am răcit.", en:"I've been coughing for a week and my throat hurts. I think I've caught a cold."},
   {speaker:"Medic", ro:"Ați avut febră?", en:"Have you had a fever?"},
   {speaker:"Pacient", ro:"Da, acum trei zile am avut treizeci și opt de grade.", en:"Yes, three days ago I had thirty-eight degrees."},
   {speaker:"Medic", ro:"Înțeleg. Ar trebui să vă odihniți și să beți multe lichide.", en:"I see. You should rest and drink plenty of fluids."},
   {speaker:"Pacient", ro:"Am nevoie de analize?", en:"Do I need tests?"},
   {speaker:"Medic", ro:"Deocamdată nu. Vă dau o rețetă, iar dacă nu vă simțiți mai bine în trei zile, reveniți.", en:"Not for now. I'll give you a prescription, and if you don't feel better in three days, come back."}
  ]},
 {id:"d_a2u5", title:"Vizionăm un apartament", titleEn:"Viewing a flat", level:"a2_1",
  lines:[
   {speaker:"Proprietar", ro:"Acesta este apartamentul. L-am renovat anul trecut.", en:"This is the flat. I renovated it last year."},
   {speaker:"Chiriaș", ro:"Se vede. Cât este chiria și ce include?", en:"You can tell. How much is the rent and what does it include?"},
   {speaker:"Proprietar", ro:"Cinci sute de euro. Întreținerea nu este inclusă.", en:"Five hundred euros. Maintenance isn't included."},
   {speaker:"Chiriaș", ro:"Și garanția?", en:"And the deposit?"},
   {speaker:"Proprietar", ro:"O chirie. O primiți înapoi la sfârșitul contractului.", en:"One month's rent. You get it back at the end of the contract."},
   {speaker:"Chiriaș", ro:"Vecinii sunt liniștiți?", en:"Are the neighbours quiet?"},
   {speaker:"Proprietar", ro:"Foarte. Sunt o familie cu doi copii și o doamnă în vârstă.", en:"Very. There's a family with two children and an elderly lady."},
   {speaker:"Chiriaș", ro:"Îmi place. Când putem semna contractul?", en:"I like it. When can we sign the contract?"}
  ]},
 {id:"d_b1u1", title:"Munca de acasă", titleEn:"Working from home", level:"b1_1",
  lines:[
   {speaker:"Alex", ro:"Care este părerea ta despre munca de acasă?", en:"What's your opinion about working from home?"},
   {speaker:"Ioana", ro:"Cred că e important să avem flexibilitate, dar mi se pare că lipsește contactul cu colegii.", en:"I think it's important to have flexibility, but I feel like contact with colleagues is missing."},
   {speaker:"Alex", ro:"Sunt de acord. E bine să lucrăm de acasă câteva zile, dar nu în fiecare zi.", en:"I agree. It's good to work from home a few days, but not every day."},
   {speaker:"Ioana", ro:"Exact. Depinde și de tipul de job — pentru unii e mai potrivit decât pentru alții.", en:"Exactly. It also depends on the type of job — it suits some more than others."}
  ]},

 /* ---------- A2.1 units 6–8 ---------- */
 {id:"d_a2u6", title:"Interviu pentru un post", titleEn:"A job interview", level:"a2_1",
  lines:[
   {speaker:"Angajator", ro:"Bună ziua! Luați loc, vă rog. Povestiți-mi puțin despre dumneavoastră.", en:"Good day! Have a seat, please. Tell me a little about yourself."},
   {speaker:"Candidat", ro:"Mulțumesc. Am terminat facultatea de economie acum trei ani și de atunci lucrez în contabilitate.", en:"Thank you. I finished the economics faculty three years ago and since then I've worked in accounting."},
   {speaker:"Angajator", ro:"De ce vreți să schimbați locul de muncă?", en:"Why do you want to change jobs?"},
   {speaker:"Candidat", ro:"Îmi place ce fac, dar vreau o echipă mai mare și mai multă responsabilitate.", en:"I like what I do, but I want a bigger team and more responsibility."},
   {speaker:"Angajator", ro:"Ce salariu aveți în vedere?", en:"What salary do you have in mind?"},
   {speaker:"Candidat", ro:"M-am gândit la ceva în jur de opt mii de lei net, dar sunt deschis la discuții.", en:"I was thinking of something around eight thousand lei net, but I'm open to discussion."},
   {speaker:"Angajator", ro:"Bine. Vă anunțăm până vineri.", en:"Good. We'll let you know by Friday."}
  ]},
 {id:"d_a2u7", title:"Cum e noul coleg?", titleEn:"What's the new colleague like?", level:"a2_1",
  lines:[
   {speaker:"Dana", ro:"Ai cunoscut-o pe Ioana, colega nouă?", en:"Have you met Ioana, the new colleague?"},
   {speaker:"Radu", ro:"Da, ieri. Mi s-a părut foarte deschisă.", en:"Yes, yesterday. She seemed very open to me."},
   {speaker:"Dana", ro:"Așa e. E genul de om care întreabă când nu știe ceva.", en:"That's right. She's the kind of person who asks when she doesn't know something."},
   {speaker:"Radu", ro:"Asta apreciez. Colegul de dinainte era mai închis și nu spunea niciodată nimic.", en:"That's what I appreciate. The colleague before was more closed off and never said anything."},
   {speaker:"Dana", ro:"Da, era cam timid. Ioana pare mai sigură pe ea.", en:"Yes, he was rather shy. Ioana seems more sure of herself."},
   {speaker:"Radu", ro:"Sper să rămână. Avem nevoie de cineva răbdător în echipă.", en:"I hope she stays. We need someone patient on the team."}
  ]},
 {id:"d_a2u8", title:"La piață", titleEn:"At the market", level:"a2_1",
  lines:[
   {speaker:"Vânzătoare", ro:"Bună ziua! Ce vă dau?", en:"Good day! What can I get you?"},
   {speaker:"Client", ro:"Aș vrea un kilogram de roșii și o legătură de pătrunjel.", en:"I'd like a kilogram of tomatoes and a bunch of parsley."},
   {speaker:"Vânzătoare", ro:"Roșiile sunt de grădină, foarte bune pentru salată. Altceva?", en:"The tomatoes are homegrown, very good for salad. Anything else?"},
   {speaker:"Client", ro:"Aveți smântână? Fac sarmale duminică.", en:"Do you have sour cream? I'm making sarmale on Sunday."},
   {speaker:"Vânzătoare", ro:"Sigur că am. Smântână de casă, groasă. Cu ce carne le faceți?", en:"Of course I do. Homemade sour cream, thick. What meat are you making them with?"},
   {speaker:"Client", ro:"Cu porc și puțină vită, cum făcea bunica.", en:"With pork and a little beef, the way my grandmother used to."},
   {speaker:"Vânzătoare", ro:"Așa e cel mai bine. Douăzeci și cinci de lei în total.", en:"That's the best way. Twenty-five lei in total."}
  ]},

 /* ---------- A2.2 ---------- */
 {id:"d_a2_2u2", title:"La bancă", titleEn:"At the bank", level:"a2_2",
  lines:[
   {speaker:"Funcționar", ro:"Bună ziua! Cu ce vă pot ajuta?", en:"Good day! How can I help you?"},
   {speaker:"Client", ro:"Aș vrea să deschid un cont curent. Ce acte îmi trebuie?", en:"I'd like to open a current account. What documents do I need?"},
   {speaker:"Funcționar", ro:"Buletinul sau pașaportul și o dovadă de adresă. Aveți permis de ședere?", en:"Your ID card or passport and proof of address. Do you have a residence permit?"},
   {speaker:"Client", ro:"Da, îl am la mine. Se percepe vreun comision lunar?", en:"Yes, I have it with me. Is there a monthly fee?"},
   {speaker:"Funcționar", ro:"Primul an e gratuit, apoi cinci lei pe lună. Completați formularul acesta, vă rog.", en:"The first year is free, then five lei a month. Fill in this form, please."},
   {speaker:"Client", ro:"În cât timp primesc cardul?", en:"How long until I get the card?"},
   {speaker:"Funcționar", ro:"În cinci zile lucrătoare, la ghișeul de aici sau prin poștă.", en:"In five working days, at the counter here or by post."}
  ]},
 {id:"d_a2_2u3", title:"Am o problemă cu produsul", titleEn:"I have a problem with the product", level:"a2_2",
  lines:[
   {speaker:"Client", ro:"Nu vă supărați, am cumpărat aspiratorul acesta acum două săptămâni și s-a stricat.", en:"Excuse me, I bought this vacuum cleaner two weeks ago and it's broken."},
   {speaker:"Vânzător", ro:"Îmi pare rău. Aveți bonul fiscal?", en:"I'm sorry. Do you have the receipt?"},
   {speaker:"Client", ro:"Da, poftiți. Este încă în garanție, nu?", en:"Yes, here you are. It's still under warranty, isn't it?"},
   {speaker:"Vânzător", ro:"Da, garanția e de doi ani. Putem să îl reparăm sau să îl înlocuim.", en:"Yes, the warranty is two years. We can repair it or replace it."},
   {speaker:"Client", ro:"Aș prefera să îl înlocuiți, dacă se poate.", en:"I'd prefer you to replace it, if possible."},
   {speaker:"Vânzător", ro:"Sigur. Completați o cerere și primiți altul în trei zile.", en:"Certainly. Fill in a request and you'll get another one in three days."}
  ]},
 {id:"d_a2_2u5", title:"În magazin", titleEn:"In the shop", level:"a2_2",
  lines:[
   {speaker:"Vânzătoare", ro:"Bună ziua! Căutați ceva anume?", en:"Good day! Are you looking for something in particular?"},
   {speaker:"Client", ro:"Da, un palton pentru iarnă. Ce mărime credeți că port?", en:"Yes, a winter coat. What size do you think I wear?"},
   {speaker:"Vânzătoare", ro:"Cred că patruzeci. Vreți să probați acesta?", en:"I think forty. Would you like to try this one on?"},
   {speaker:"Client", ro:"Da. Unde e cabina de probă?", en:"Yes. Where's the fitting room?"},
   {speaker:"Vânzătoare", ro:"În spate, la dreapta.", en:"At the back, on the right."},
   {speaker:"Client", ro:"E puțin cam strâmt la umeri. Aveți unul mai larg?", en:"It's a bit tight at the shoulders. Do you have a looser one?"},
   {speaker:"Vânzătoare", ro:"Vă aduc mărimea patruzeci și doi. Vă stă foarte bine culoarea, apropo.", en:"I'll bring you a forty-two. The colour suits you very well, by the way."}
  ]},
 {id:"d_a2_2u7", title:"Cum era pe atunci", titleEn:"How it was back then", level:"a2_2",
  lines:[
   {speaker:"Bunica", ro:"Pe atunci locuiam la țară, într-o casă mică.", en:"Back then we lived in the countryside, in a small house."},
   {speaker:"Nepot", ro:"Și mergeai la școală în sat?", en:"And did you go to school in the village?"},
   {speaker:"Bunica", ro:"În fiecare zi mergeam pe jos, patru kilometri. Iarna era greu.", en:"Every day I walked, four kilometres. In winter it was hard."},
   {speaker:"Nepot", ro:"Și ce s-a întâmplat în ziua aceea despre care povesteai?", en:"And what happened on that day you were telling me about?"},
   {speaker:"Bunica", ro:"Mergeam spre școală și dintr-odată a început o furtună. M-am adăpostit la o vecină.", en:"I was walking to school and suddenly a storm started. I took shelter at a neighbour's."},
   {speaker:"Nepot", ro:"Și după aceea?", en:"And after that?"},
   {speaker:"Bunica", ro:"După aceea m-a dus tata cu căruța. Nu am ajuns la școală în ziua aceea.", en:"After that my father took me with the cart. I didn't get to school that day."}
  ]},

 /* ---------- B1.1 ---------- */
 {id:"d_b1u3", title:"Ne-am certat", titleEn:"We had an argument", level:"b1_1",
  lines:[
   {speaker:"Ana", ro:"Ești supărată pe mine? Simt că ceva nu e în regulă.", en:"Are you annoyed with me? I feel like something isn't right."},
   {speaker:"Ioana", ro:"Nu sunt supărată, sunt dezamăgită. E altceva.", en:"I'm not annoyed, I'm disappointed. That's something else."},
   {speaker:"Ana", ro:"Îmi pare rău. Nu mi-am dat seama că te-a deranjat atât.", en:"I'm sorry. I didn't realise it bothered you that much."},
   {speaker:"Ioana", ro:"Nu e vorba de o singură dată. Se întâmplă des și nu spui nimic.", en:"It's not about one time. It happens often and you don't say anything."},
   {speaker:"Ana", ro:"Ai dreptate. Ar fi trebuit să vorbesc cu tine mai devreme.", en:"You're right. I should have spoken to you earlier."},
   {speaker:"Ioana", ro:"Hai să lăsăm asta. Important e că vorbim acum.", en:"Let's leave it. What matters is that we're talking now."}
  ]},
 {id:"d_b1u6", title:"La ghișeu, din nou", titleEn:"At the counter, again", level:"b1_1",
  lines:[
   {speaker:"Funcționară", ro:"Următorul, vă rog! Ce doriți?", en:"Next, please! What do you need?"},
   {speaker:"Solicitant", ro:"Aș vrea să depun o cerere pentru certificatul de rezidență.", en:"I'd like to submit an application for a residence certificate."},
   {speaker:"Funcționară", ro:"Aveți dosarul complet? Trebuie copie după pașaport, dovadă de adresă și cerere semnată.", en:"Is your file complete? You need a copy of your passport, proof of address and a signed application."},
   {speaker:"Solicitant", ro:"Cred că da. Am adus tot ce scria pe site.", en:"I think so. I brought everything the website listed."},
   {speaker:"Funcționară", ro:"Lipsește ștampila de la primărie pe dovada de adresă.", en:"The stamp from the town hall is missing on the proof of address."},
   {speaker:"Solicitant", ro:"Și dacă o aduc mâine, se poate rezolva?", en:"And if I bring it tomorrow, can it be sorted out?"},
   {speaker:"Funcționară", ro:"Da, dar termenul de depunere e vineri. Certificatul se eliberează în treizeci de zile.", en:"Yes, but the submission deadline is Friday. The certificate is issued within thirty days."}
  ]},
 {id:"d_b1u8", title:"Să cumpărăm sau să stăm cu chirie?", titleEn:"Buy or keep renting?", level:"b1_1",
  lines:[
   {speaker:"Radu", ro:"Dacă am lua un credit acum, am plăti cam cât plătim pe chirie.", en:"If we took out a loan now, we'd pay about what we pay in rent."},
   {speaker:"Ilinca", ro:"Da, dar rata rămâne douăzeci de ani. Chiria o poți opri oricând.", en:"Yes, but the instalment stays for twenty years. You can stop renting any time."},
   {speaker:"Radu", ro:"E adevărat. Pe de altă parte, la sfârșit apartamentul e al nostru.", en:"That's true. On the other hand, at the end the flat is ours."},
   {speaker:"Ilinca", ro:"Mă îngrijorează dobânda. Dacă crește, nu ne-am mai permite.", en:"The interest worries me. If it goes up, we wouldn't be able to afford it any more."},
   {speaker:"Radu", ro:"Atunci hai să mai așteptăm un an și să strângem un avans mai mare.", en:"Then let's wait another year and save a bigger deposit."},
   {speaker:"Ilinca", ro:"În fond, nu ne grăbește nimeni. E o decizie pentru douăzeci de ani.", en:"After all, nobody's rushing us. It's a decision for twenty years."}
  ]}
];

/* ===================== READING TEXTS ===================== */
var READING_TEXTS = [
 {id:"r_u1", title:"Un mesaj nou", titleEn:"A new message", level:"a1_1", format:"message", wordCount:41,
  ro:"Bună! Numele meu este Elena. Sunt din România, din orașul Cluj-Napoca. Sunt profesoară de matematică. Vorbesc română și engleză, iar acum învăț puțină franceză. Am douăzeci și opt de ani. Familia mea este mică: am un frate și o soră.",
  en:"Hi! My name is Elena. I'm from Romania, from the city of Cluj-Napoca. I'm a math teacher. I speak Romanian and English, and now I'm learning a little French. I am twenty-eight years old. My family is small: I have one brother and one sister.",
  glossary:{"profesoară":"teacher (f)", "matematică":"mathematics", "învăț":"I learn/study", "mică":"small (f)"}},
 {id:"r_u2", title:"Familia lui Andrei", titleEn:"Andrei's family", level:"a1_1", format:"short story", wordCount:55,
  ro:"Andrei are o familie mare. Tatăl lui, Ion, este inginer, iar mama lui, Maria, este medic. Andrei are doi frați: Radu, care are treizeci de ani, și Bianca, care are douăzeci și doi de ani. Bunicii lor locuiesc la țară și au o casă frumoasă cu grădină. În fiecare vară, toată familia merge la bunici.",
  en:"Andrei has a big family. His father, Ion, is an engineer, and his mother, Maria, is a doctor. Andrei has two siblings: Radu, who is thirty, and Bianca, who is twenty-two. Their grandparents live in the countryside and have a beautiful house with a garden. Every summer, the whole family goes to their grandparents'.",
  glossary:{"inginer":"engineer","medic":"doctor","grădină":"garden","vară":"summer"}},
 {id:"r_u3", title:"Programul Cristinei", titleEn:"Cristina's schedule", level:"a1_1", format:"schedule/diary", wordCount:59,
  ro:"Cristina se trezește în fiecare zi la ora șapte. Dimineața bea o cafea și mănâncă un mic dejun rapid. La ora opt și jumătate pleacă la serviciu cu metroul. Lucrează de luni până vineri, între orele nouă și șapte. Seara merge la sală sau se întâlnește cu prietenii. Duminica nu lucrează — de obicei citește sau gătește pentru toată săptămâna.",
  en:"Cristina wakes up every day at seven o'clock. In the morning she drinks a coffee and eats a quick breakfast. At half past eight she leaves for work by subway. She works Monday to Friday, between nine and seven. In the evening she goes to the gym or meets up with friends. On Sundays she doesn't work — she usually reads or cooks for the whole week.",
  glossary:{"mic dejun":"breakfast","metroul":"the subway","gătește":"cooks"}},
 {id:"r_u4", title:"Meniul zilei", titleEn:"Menu of the day", level:"a1_1", format:"menu", wordCount:42,
  ro:"RESTAURANT LA BUNICA — MENIUL ZILEI\n\nCiorbă de legume — 18 lei\nSupă de pui — 20 lei\n\nPește cu cartofi — 45 lei\nPui cu legume — 38 lei\nSarmale cu mămăligă — 42 lei\n\nSalată verde — 15 lei\nBrânză de oaie — 22 lei\n\nApă plată — 8 lei\nCafea — 10 lei\nBere — 14 lei\nVin roșu — 18 lei",
  en:"RESTAURANT AT GRANDMA'S — MENU OF THE DAY. Vegetable sour soup 18 lei. Chicken soup 20 lei. Fish with potatoes 45 lei. Chicken with vegetables 38 lei. Sarmale with polenta 42 lei. Green salad 15 lei. Sheep's cheese 22 lei. Still water 8 lei. Coffee 10 lei. Beer 14 lei. Red wine 18 lei.",
  glossary:{"ciorbă":"sour soup","pui":"chicken","cartofi":"potatoes","sarmale":"cabbage rolls (national dish)","mămăligă":"polenta","roșu":"red"}},
 {id:"r_u5", title:"Un mesaj despre cumpărături", titleEn:"A message about shopping", level:"a1_1", format:"text message", wordCount:50,
  ro:"Bună, Ioana! Sunt în oraș acum. Am fost la magazinul din centru și am găsit o rochie foarte frumoasă. Costă o sută cincizeci de lei — nu este ieftină, dar îmi place mult. Am cumpărat și pantofi negri, la reducere. Tu ce faci? Vrei să bem o cafea la ora cinci?",
  en:"Hi, Ioana! I'm in town now. I went to the shop in the center and found a very beautiful dress. It costs one hundred and fifty lei — it isn't cheap, but I like it a lot. I also bought black shoes, on sale. What are you doing? Do you want to have a coffee at five?",
  glossary:{"găsit":"found","reducere":"discount, sale","frumoasă":"beautiful"}},
 {id:"r_u6", title:"Cum ajungi la muzeu", titleEn:"How to get to the museum", level:"a1_1", format:"directions / notice", wordCount:59,
  ro:"Muzeul Satului este în nordul orașului, aproape de parcul Herăstrău. De la gară puteți lua metroul până la stația Aviatorilor. Apoi mergeți drept înainte cinci minute pe jos. Muzeul este la dreapta, vizavi de un restaurant mare. Este deschis de marți până duminică, între orele zece și optsprezece. Luni este închis. Un bilet costă douăzeci și cinci de lei.",
  en:"The Village Museum is in the north of the city, near Herăstrău park. From the station you can take the subway to Aviatorilor station. Then walk straight ahead for five minutes. The museum is on the right, opposite a large restaurant. It's open Tuesday to Sunday, between ten and eighteen. It's closed on Mondays. A ticket costs twenty-five lei.",
  glossary:{"nordul":"the north","stația":"the stop/station","deschis":"open","închis":"closed","marți":"Tuesday"}},
 {id:"r_u7", title:"Anunț imobiliar", titleEn:"Property listing", level:"a1_1", format:"advertisement", wordCount:60,
  ro:"DE ÎNCHIRIAT — apartament cu două camere, etajul patru, în centru.\n\nApartamentul are o sufragerie mare cu balcon, un dormitor, o bucătărie mobilată și o baie. Ferestrele dau spre un parc liniștit. Există frigider, mașină de spălat și dulapuri în fiecare cameră.\n\nChiria este de patru sute cincizeci de euro pe lună. Blocul are lift. Nu se acceptă animale de companie.",
  en:"FOR RENT — two-room flat, fourth floor, in the center. The flat has a large living room with a balcony, a bedroom, a furnished kitchen and a bathroom. The windows look onto a quiet park. There is a fridge, a washing machine and wardrobes in every room. The rent is four hundred and fifty euros a month. The building has a lift. No pets accepted.",
  glossary:{"De închiriat":"for rent","mobilată":"furnished","liniștit":"quiet","mașină de spălat":"washing machine","lift":"lift, elevator","animale de companie":"pets"}},
 {id:"r_u8", title:"Prognoza meteo", titleEn:"Weather forecast", level:"a1_1", format:"forecast", wordCount:52,
  ro:"PROGNOZA PENTRU SĂPTĂMÂNA VIITOARE\n\nLuni și marți va fi frumos, cu soare și douăzeci și două de grade. Miercuri se răcește: plouă toată ziua și bate vântul.\n\nJoi și vineri vremea se îmbunătățește, dar rămâne rece — doar treisprezece grade dimineața. La munte va ninge din nou.\n\nÎn weekend așteptăm din nou soare.",
  en:"FORECAST FOR NEXT WEEK. Monday and Tuesday will be nice, sunny and twenty-two degrees. Wednesday turns colder: it will rain all day and be windy. Thursday and Friday the weather improves, but stays cold — only thirteen degrees in the morning. In the mountains it will snow again. At the weekend we expect sun once more.",
  glossary:{"prognoza":"the forecast","se răcește":"it turns colder","se îmbunătățește":"improves","rămâne":"remains","din nou":"again","așteptăm":"we expect"}},
 {id:"r_a12u1", title:"Profilul unui coleg", titleEn:"A colleague's profile", level:"a1_2", format:"social post", wordCount:67,
  ro:"Mă numesc Victor și am treizeci și doi de ani. Sunt inginer și lucrez la o firmă de construcții din Timișoara. Programul meu începe la opt dimineața și se termină pe la cinci. De obicei merg la birou cu bicicleta, dar iarna iau tramvaiul. Nu lucrez niciodată duminica. În timpul liber alerg, citesc și gătesc pentru prieteni. Uneori merg la un meci de fotbal cu colegii mei.",
  en:"My name is Victor and I'm thirty-two years old. I'm an engineer and I work at a construction firm in Timișoara. My working day starts at eight in the morning and ends around five. I usually go to the office by bike, but in winter I take the tram. I never work on Sundays. In my free time I run, read and cook for friends. Sometimes I go to a football match with my colleagues.",
  glossary:{"construcții":"construction","iarna":"in winter","meci":"match, game","bicicleta":"the bicycle"}},
 {id:"r_a12u3", title:"Mesaje despre o întâlnire", titleEn:"Messages about a meeting", level:"a1_2", format:"text messages", wordCount:47,
  ro:"— Bună, Ana! Ești liberă joi seara?\n— Bună! Joi sunt ocupată, am o programare la medic. Vineri poți?\n— Vineri e perfect. La ce oră?\n— Pe la șapte? Putem merge la restaurantul nou din centru.\n— Sună bine. Ne vedem vineri, pe 14 martie, la șapte.\n— Perfect! Te sun dacă întârzii.",
  en:"— Hi, Ana! Are you free on Thursday evening? — Hi! On Thursday I'm busy, I have a doctor's appointment. Can you do Friday? — Friday is perfect. What time? — Around seven? We could go to the new restaurant in the center. — Sounds good. See you Friday, the 14th of March, at seven. — Perfect! I'll call you if I'm running late.",
  glossary:{"întârzii":"I'm late / I run late","Ne vedem":"See you","poți":"can you","Sună bine":"Sounds good"}},
 {id:"r_a12u5", title:"Anunț în gară", titleEn:"Station announcement", level:"a1_2", format:"announcement", wordCount:47,
  ro:"Atenție, călători! Trenul InterRegio 1682 cu plecare spre Brașov, programat la ora nouă și zece minute, are o întârziere de aproximativ douăzeci de minute. Trenul va sosi la peronul patru. Vă rugăm să aveți grijă la urcarea în tren. Vă mulțumim pentru înțelegere și vă dorim călătorie plăcută!",
  en:"Attention, passengers! The InterRegio 1682 train departing for Brașov, scheduled for nine ten, has a delay of approximately twenty minutes. The train will arrive at platform four. Please take care when boarding. Thank you for your understanding and we wish you a pleasant journey!",
  glossary:{"călători":"passengers, travelers","plecare":"departure","programat":"scheduled","aproximativ":"approximately","urcarea":"the boarding","înțelegere":"understanding"}},
 {id:"r_a12u7", title:"Două oferte", titleEn:"Two offers", level:"a1_2", format:"advertisement", wordCount:54,
  ro:"MAGAZINUL CENTRAL — OFERTE DE TOAMNĂ\n\nGeacă de iarnă, model clasic: 320 lei. Culori: negru, gri, albastru.\nGeacă sport, model nou: 450 lei. Mai ușoară și mai caldă decât modelul clasic.\n\nPantofi de piele: 280 lei. Cea mai bună calitate din magazin.\nPantofi sport: 190 lei. Mai ieftini, dar mai puțin rezistenți.\n\nToate produsele au reducere de 10% până duminică.",
  en:"CENTRAL STORE — AUTUMN OFFERS. Winter jacket, classic model: 320 lei. Colors: black, gray, blue. Sports jacket, new model: 450 lei. Lighter and warmer than the classic model. Leather shoes: 280 lei. The best quality in the store. Sports shoes: 190 lei. Cheaper, but less durable. All products have a 10% discount until Sunday.",
  glossary:{"geacă":"jacket","piele":"leather","rezistenți":"durable, hard-wearing","gri":"gray","produsele":"the products"}},
 {id:"r_civ_oath", title:"Jurământul de credință", titleEn:"The oath of allegiance", level:"civic", format:"official text", wordCount:20,
  ro:"Jur să fiu devotat patriei și poporului român, să apăr drepturile și interesele naționale, să respect Constituția și legile României.",
  en:"I swear to be devoted to the homeland and the Romanian people, to defend the national rights and interests, to respect the Constitution and the laws of Romania.",
  glossary:{"Jur":"I swear (a jura)","devotat":"devoted","patriei":"to the homeland (dative of patrie)","poporului":"to the people (dative of popor)","apăr":"I defend (a apăra)","drepturile":"the rights","interesele":"the interests","naționale":"national (pl.)","respect":"I respect (a respecta)","legile":"the laws"}},
 {id:"r_civ_imn", title:"Deșteaptă-te, române! — strofele oficiale", titleEn:"The official stanzas of the anthem", level:"civic", format:"anthem", wordCount:126,
  ro:"Deșteaptă-te, române, din somnul cel de moarte,\nÎn care te-adânciră barbarii de tirani!\nAcum ori niciodată, croiește-ți altă soartă,\nLa care să se-nchine și cruzii tăi dușmani!\n\nAcum ori niciodată să dăm dovezi la lume\nCă-n aste mâni mai curge un sânge de roman,\nȘi că-n a noastre piepturi păstrăm cu fală-un nume\nTriumfător în lupte, un nume de Traian!\n\nPriviți, mărețe umbre, Mihai, Ștefan, Corvine,\nRomâna națiune, ai voștri strănepoți,\nCu brațele armate, cu focul vostru-n vine,\n„Viață-n libertate ori moarte!” strigă toți.\n\nPreoți, cu crucea-n frunte căci oastea e creștină,\nDeviza-i libertate și scopul ei preasfânt.\nMurim mai bine-n luptă, cu glorie deplină,\nDecât să fim sclavi iarăși în vechiul nost' pământ!",
  en:"Awaken thee, Romanian, from the sleep of death into which you have been sunk by barbaric tyrants! Now or never, forge yourself a new fate, before which even your cruel enemies will bow. Now or never let us give proof to the world that in these veins still flows Roman blood, and that in our breasts we proudly bear a name triumphant in battle, the name of Trajan. Behold, great shades — Mihai, Ștefan, Corvinus — the Romanian nation, your great-grandchildren, with weapons in their arms and your fire in their veins, all cry 'Life in freedom, or death!' Priests, lead with the cross before you, for our army is Christian; its motto is liberty and its aim most holy. Better to die in battle in full glory than to be slaves once more upon our ancient land.",
  /* Verse has to be glossed line for line: a prose paragraph makes the reader
     hunt for which clause belongs to which line, and the anthem's word order is
     poetic enough that the mapping is not guessable. Kept close to the Romanian
     rather than polished into English verse. */
  lineEn:["Awaken thee, Romanian, from the sleep of death",
          "into which barbaric tyrants have sunk you!",
          "Now or never, forge yourself another fate",
          "to which even your cruel enemies will bow!",
          "",
          "Now or never let us give the world proof",
          "that in these hands there still runs Roman blood,",
          "and that in our breasts we proudly bear a name",
          "triumphant in battle — the name of Trajan!",
          "",
          "Behold, great shades — Mihai, Ștefan, Corvinus —",
          "the Romanian nation, your great-grandchildren,",
          "with weapons in their arms, with your fire in their veins,",
          "“Life in freedom, or death!” they all cry.",
          "",
          "Priests, lead with the cross before you, for the army is Christian,",
          "its motto is liberty and its purpose most holy.",
          "Better we die in battle, in full glory,",
          "than be slaves once more upon our ancient land!"],
  glossary:{"Deșteaptă-te":"awaken (yourself)","somnul":"the sleep","moarte":"death","tirani":"tyrants","soartă":"fate, destiny","dușmani":"enemies","dovezi":"proofs","sânge":"blood","piepturi":"breasts, chests","umbre":"shades, shadows","strănepoți":"great-grandchildren","libertate":"freedom","oastea":"the army","glorie":"glory","sclavi":"slaves","pământ":"land, earth"}},
 {id:"r_civ_stat", title:"Statul român pe scurt", titleEn:"The Romanian state in brief", level:"civic", format:"reference", wordCount:85,
  ro:"România este stat național, suveran și independent, unitar și indivizibil. Forma de guvernământ este republica. Capitala este București. Limba oficială este limba română. Drapelul are trei culori așezate vertical: albastru, galben și roșu. Ziua națională este 1 decembrie. Imnul național este „Deșteaptă-te, române!”.\n\nParlamentul are două camere: Camera Deputaților și Senatul. Președintele este ales prin vot direct pentru un mandat de cinci ani și poate avea cel mult două mandate. Guvernul este condus de prim-ministru. Constituția actuală a fost adoptată în 1991 și revizuită în 2003.",
  en:"Romania is a national, sovereign and independent, unitary and indivisible state. The form of government is a republic. The capital is Bucharest. The official language is Romanian. The flag has three colors arranged vertically: blue, yellow and red. The national day is 1 December. The national anthem is 'Deșteaptă-te, române!'. Parliament has two chambers: the Chamber of Deputies and the Senate. The President is elected by direct vote for a five-year term and may serve at most two terms. The Government is led by the Prime Minister. The current Constitution was adopted in 1991 and revised in 2003.",
  glossary:{"suveran":"sovereign","indivizibil":"indivisible","guvernământ":"government (form of)","așezate":"arranged, placed","mandat":"term of office","revizuită":"revised","Deputaților":"of the Deputies"}},
 {id:"r_civ_geo", title:"Geografia României", titleEn:"Geography of Romania", level:"civic", format:"reference", wordCount:91,
  ro:"România se află în sud-estul Europei. Are graniță cu cinci țări: Ungaria la vest, Serbia la sud-vest, Bulgaria la sud, Ucraina la nord și est, și Republica Moldova la est. La sud-est se află Marea Neagră.\n\nMunții Carpați traversează țara. Cel mai înalt vârf este Vârful Moldoveanu, de 2544 de metri. Dunărea este cel mai important fluviu și se varsă în Marea Neagră prin Delta Dunării.\n\nRegiunile istorice sunt Transilvania, Muntenia, Moldova, Oltenia, Banat, Crișana, Maramureș și Dobrogea. Orașe mari sunt București, Cluj-Napoca, Timișoara, Iași, Constanța și Brașov.",
  en:"Romania is located in south-eastern Europe. It borders five countries: Hungary to the west, Serbia to the south-west, Bulgaria to the south, Ukraine to the north and east, and the Republic of Moldova to the east. To the south-east lies the Black Sea. The Carpathian Mountains cross the country. The highest peak is Moldoveanu Peak, at 2,544 metres. The Danube is the most important river and flows into the Black Sea through the Danube Delta. The historical regions are Transylvania, Muntenia, Moldova, Oltenia, Banat, Crișana, Maramureș and Dobrogea. Major cities are Bucharest, Cluj-Napoca, Timișoara, Iași, Constanța and Brașov.",
  glossary:{"se află":"is located","vest":"west","sud":"south","nord":"north","est":"east","vârf":"peak","se varsă":"flows into, empties","Deltă":"delta","regiunile":"the regions"}},
 {id:"r_civ_ist", title:"Repere din istoria României", titleEn:"Key points in Romanian history", level:"civic", format:"reference", wordCount:70,
  ro:"În 1859, Alexandru Ioan Cuza a fost ales domn atât în Moldova, cât și în Țara Românească. Acest moment se numește Unirea Principatelor Române.\n\nÎn 1877–1878, România și-a câștigat independența față de Imperiul Otoman.\n\nLa 1 decembrie 1918, la Alba Iulia, Transilvania s-a unit cu România. Ziua aceasta este acum Ziua Națională.\n\nÎn decembrie 1989, Revoluția a pus capăt regimului comunist.\n\nRomânia a intrat în NATO în 2004 și în Uniunea Europeană la 1 ianuarie 2007.",
  en:"In 1859, Alexandru Ioan Cuza was elected ruler of both Moldavia and Wallachia. This moment is called the Union of the Romanian Principalities. In 1877–1878, Romania won its independence from the Ottoman Empire. On 1 December 1918, at Alba Iulia, Transylvania united with Romania. That day is now the National Day. In December 1989, the Revolution ended the communist regime. Romania joined NATO in 2004 and the European Union on 1 January 2007.",
  glossary:{"domn":"ruler, prince","Principatelor":"of the Principalities","și-a câștigat":"won (for itself)","s-a unit":"united","a pus capăt":"put an end to","regimului":"of the regime","a intrat":"entered, joined"}},
 {id:"r_a2u1", title:"Un e-mail de la Maria", titleEn:"An email from Maria", level:"a2_1", format:"email", wordCount:97,
  ro:"Salut Sorin,\n\nÎți scriu ca să-ți povestesc despre weekendul trecut. Sâmbătă dimineața am plecat la munte cu Ioana și cu Vlad. Am ajuns pe la ora zece și am făcut o drumeție de trei ore. A fost obositor, dar peisajul a fost superb!\n\nLa prânz am mâncat la o cabană — am comandat ciorbă și mămăligă cu brânză. Seara ne-am întors în oraș și am vizionat un film.\n\nDuminică am dormit până târziu, apoi am făcut curățenie și am pregătit mâncare pentru săptămâna asta. Sper că și tu ai avut un weekend plăcut!\n\nCu drag,\nMaria",
  en:"Hi Sorin, I'm writing to tell you about last weekend. On Saturday morning we left for the mountains with Ioana and Vlad. We arrived around ten and went on a three-hour hike. It was tiring, but the scenery was superb! At noon we ate at a mountain cabin — we ordered ciorbă (sour soup) and mămăligă (polenta) with cheese. In the evening we went back to the city and watched a movie. On Sunday I slept in, then cleaned and prepared food for this week. I hope you also had a nice weekend! Love, Maria",
  glossary:{"drumeție":"hike","cabană":"mountain cabin/lodge","ciorbă":"sour soup","mămăligă":"polenta","curățenie":"cleaning"}},
 {id:"r_a2u3", title:"Confirmarea rezervării", titleEn:"Booking confirmation", level:"a2_1", format:"email", wordCount:86,
  ro:"Stimate domnule Ionescu,\n\nVă confirmăm rezervarea dumneavoastră la Hotel Central, pentru perioada 12–15 iulie.\n\nAți rezervat o cameră dublă la etajul doi, cu mic dejun inclus. Cazarea începe de la ora paisprezece, iar camera trebuie eliberată până la ora douăsprezece în ziua plecării.\n\nPrețul total este de opt sute cincizeci de lei. Plata se poate face la recepție, cu cardul sau în numerar.\n\nDacă doriți să anulați rezervarea, vă rugăm să ne anunțați cu cel puțin patruzeci și opt de ore înainte.\n\nCu stimă,\nRecepția Hotel Central",
  en:"Dear Mr Ionescu, We confirm your reservation at Hotel Central for the period 12–15 July. You have booked a double room on the second floor, with breakfast included. Check-in begins at two p.m., and the room must be vacated by twelve o'clock on the day of departure. The total price is eight hundred and fifty lei. Payment can be made at reception, by card or in cash. If you wish to cancel the reservation, please notify us at least forty-eight hours in advance. Kind regards, Hotel Central Reception",
  glossary:{"Stimate":"Dear (formal, to a man)","confirmăm":"we confirm","cazarea":"the check-in / accommodation","eliberată":"vacated","numerar":"cash","anulați":"you cancel","anunțați":"you notify","Cu stimă":"Kind regards"}},
 {id:"r_a2u5", title:"Anunț: apartament de închiriat", titleEn:"Advert: flat to rent", level:"a2_1", format:"advertisement", wordCount:80,
  ro:"Închiriez apartament cu două camere, renovat anul trecut, în zona Aviatorilor.\n\nApartamentul are living, dormitor, bucătărie utilată și baie. Este mobilat complet și are aer condiționat. Etajul trei din opt, bloc cu lift.\n\nChirie: 500 de euro pe lună. Întreținerea nu este inclusă și costă în medie 150 de lei iarna. Garanție: o chirie, care se returnează la sfârșitul contractului.\n\nContract minimum un an. Nu se acceptă animale. Preferabil pentru o persoană sau un cuplu fără copii.\n\nRelații la telefon după ora 17.",
  en:"I am renting a two-room flat, renovated last year, in the Aviatorilor area. The flat has a living room, bedroom, fitted kitchen and bathroom. It is fully furnished and has air conditioning. Third floor of eight, building with a lift. Rent: 500 euros a month. Maintenance is not included and costs on average 150 lei in winter. Deposit: one month's rent, returned at the end of the contract. Minimum one-year contract. No pets. Preferably for one person or a couple without children. Information by phone after 5 p.m.",
  glossary:{"Închiriez":"I am renting out","utilată":"fitted, equipped","mobilat":"furnished","lift":"lift, elevator","în medie":"on average","se returnează":"is returned","Relații":"information, enquiries"}},
 {id:"r_b1u1", title:"Munca la distanță — un articol scurt", titleEn:"Remote work — a short article", level:"b1_1", format:"article", wordCount:435,
  ro:"În ultimii ani, tot mai mulți români aleg să lucreze de acasă, cel puțin câteva zile pe săptămână. Susținătorii muncii la distanță spun că aceasta oferă mai multă flexibilitate și economisește timpul pierdut în trafic. Pe de altă parte, unii angajatori cred că este important ca echipele să se întâlnească față în față, pentru a comunica mai eficient și a construi relații mai puternice.\n\nMulți specialiști recomandă un model hibrid: câteva zile la birou, câteva zile acasă. Astfel, angajații pot beneficia de liniștea de acasă atunci când au nevoie de concentrare, dar păstrează și legătura cu colegii. Deși nu există o soluție perfectă pentru toată lumea, tot mai multe companii din România adoptă acest tip de flexibilitate.\n\nPentru companii, calculul nu este doar unul de imagine. Un birou în centrul Bucureștiului costă mult, iar dacă jumătate dintre angajați sunt prezenți la birou doar două zile pe săptămână, firma poate închiria un spațiu mai mic. În plus, o companie care acceptă munca la distanță nu mai este obligată să angajeze numai oameni din același oraș: poate căuta un specialist la Iași, la Timișoara sau într-un sat din Maramureș, fără să îi ceară să se mute.\n\nExistă însă și un preț. Mulți angajați spun că, lucrând de acasă, ziua de muncă nu se mai termină niciodată: laptopul rămâne deschis pe masa din bucătărie, iar mesajele continuă să vină și seara. Alții simt lipsa colegilor. Pentru cei tineri, care tocmai au terminat facultatea, problema este și mai serioasă, pentru că se învață enorm ascultând discuțiile din jur, iar acele discuții nu se întâmplă pe chat.\n\nApoi sunt lucrurile practice, despre care se vorbește mai rar. Cine plătește scaunul bun, monitorul, internetul mai rapid? Legea telemuncii prevede că angajatorul și angajatul stabilesc acest lucru în contract, însă în practică multe firme lasă cheltuiala în seama angajatului. Cine lucrează serios de acasă știe că un scaun nepotrivit se simte după trei luni, nu după trei zile.\n\nUn efect neașteptat se vede în afara orașelor mari. Unii oameni au profitat de flexibilitate ca să se mute înapoi în orașul natal sau la țară, unde chiria este mai mică și unde au familie. Nu toți rămân — internetul slab și lipsa serviciilor îi aduc înapoi după un an — dar tendința există și se vede în prețurile caselor din localitățile aflate la o oră de București sau de Cluj.\n\nDeocamdată, nimeni nu poate spune cum va arăta munca peste zece ani. Cert este că discuția s-a mutat: nu se mai întreabă dacă munca la distanță este posibilă, pentru că am văzut cu toții că este, ci în ce condiții funcționează bine și pentru cine.",
  en:"In recent years, more and more Romanians are choosing to work from home, at least a few days a week. Supporters of remote work say it offers more flexibility and saves time lost in traffic. On the other hand, some employers believe it's important for teams to meet face to face, in order to communicate more effectively and build stronger relationships. Many specialists recommend a hybrid model: a few days at the office, a few days at home. This way, employees can benefit from the quiet of home when they need to focus, while still keeping in touch with colleagues. Although there's no perfect solution for everyone, more and more companies in Romania are adopting this kind of flexibility. For companies, the calculation is not only about image. An office in central Bucharest costs a lot, and if half the employees are in the office only two days a week, the firm can rent a smaller space. On top of that, a company that accepts remote work is no longer obliged to hire only people from the same city: it can look for a specialist in Iași, in Timișoara or in a village in Maramureș, without asking them to move. There is a price, though. Many employees say that, working from home, the working day never ends: the laptop stays open on the kitchen table, and the messages keep coming in the evening too. Others miss their colleagues. For young people who have just finished university the problem is even more serious, because you learn an enormous amount by listening to the conversations around you, and those conversations do not happen on chat. Then there are the practical things, which get talked about less often. Who pays for the good chair, the monitor, the faster internet? The telework law provides that the employer and the employee settle this in the contract, but in practice many firms leave the expense to the employee. Anyone who works from home seriously knows that an unsuitable chair makes itself felt after three months, not after three days. An unexpected effect can be seen outside the big cities. Some people have taken advantage of the flexibility to move back to their home town or to the countryside, where the rent is lower and where they have family. Not everyone stays — poor internet and the lack of services bring them back after a year — but the trend exists and shows in house prices in the towns an hour from Bucharest or Cluj. For now, nobody can say what work will look like in ten years. What is certain is that the discussion has shifted: people no longer ask whether remote work is possible, because we have all seen that it is, but under what conditions it works well, and for whom.",
  glossary:{"închiria":"to rent (out)","telemuncii":"of telework (genitive of telemunca)","cheltuiala":"the expense","nepotrivit":"unsuitable","natal":"native, home (town)","chiria":"the rent","tendința":"the trend","deocamdată":"for now, for the time being","susținătorii":"the supporters","angajatori":"employers","eficient":"efficient(ly)","hibrid":"hybrid","concentrare":"focus/concentration"}},

 {id:"r_a2u6", title:"Anunț de angajare", titleEn:"A job advert", level:"a2_1", format:"advert", wordCount:93,
  ro:"FIRMA MEDIAPLUS ANGAJEAZĂ — asistent marketing\n\nCăutăm un coleg sau o colegă pentru echipa noastră din Timișoara.\n\nCerințe: studii superioare terminate, minimum doi ani de experiență într-un post similar, engleză la nivel avansat. Este un avantaj dacă știți să lucrați cu programe de grafică.\n\nOferim: salariu între șase și opt mii de lei net, program flexibil, două zile de lucru de acasă pe săptămână și douăzeci și cinci de zile de concediu pe an.\n\nTrimiteți CV-ul la adresa de mai jos până pe cincisprezece martie. Vom contacta numai candidații selectați pentru interviu.",
  en:"MEDIAPLUS IS HIRING — marketing assistant. We are looking for a colleague for our team in Timișoara. Requirements: completed higher education, a minimum of two years' experience in a similar position, advanced English. It is an advantage if you know how to work with graphics software. We offer: a salary between six and eight thousand lei net, flexible hours, two days of working from home per week, and twenty-five days of leave per year. Send your CV to the address below by 15 March. We will contact only the candidates selected for interview.",
  glossary:{"cerințe":"requirements","avantaj":"an advantage","oferim":"we offer","net":"after tax","candidații":"the candidates","selectați":"selected"}},

 {id:"r_a2u8", title:"Rețeta de sarmale a bunicii", titleEn:"Grandmother's sarmale recipe", level:"a2_1", format:"recipe", wordCount:101,
  ro:"Sarmalele nu sunt grele, dar cer timp. Bunica începea sâmbătă dimineața și le mânca abia duminica.\n\nÎntâi prăjești ceapa tocată mărunt, până se face aurie. Adaugi carnea — porc și puțină vită — orezul și condimentele. Amesteci bine totul.\n\nApoi iei foile de varză murată și pui câte o lingură de compoziție în fiecare. Le rulezi strâns și le așezi în oală, unul lângă altul.\n\nPui apă cât să le acopere și le fierbi la foc mic două-trei ore. Cu cât stau mai mult, cu atât sunt mai bune.\n\nSe servesc cu mămăligă și smântână. A doua zi sunt și mai gustoase.",
  en:"Sarmale are not difficult, but they take time. Grandmother would start on Saturday morning and only eat them on Sunday. First you fry finely chopped onion until it turns golden. You add the meat — pork and a little beef — the rice and the spices. Mix everything well. Then you take the pickled cabbage leaves and put a spoonful of the mixture in each. You roll them tightly and arrange them in the pot, one next to another. You add enough water to cover them and boil them on a low heat for two or three hours. The longer they sit, the better they are. They are served with polenta and sour cream. The next day they are even tastier.",
  glossary:{"cer":"they require","tocată":"chopped","mărunt":"finely","aurie":"golden","condimentele":"the spices","foile":"the leaves","murată":"pickled","compoziție":"the mixture","rulezi":"you roll","strâns":"tightly","oală":"pot","acopere":"cover","gustoase":"tasty"}},

 {id:"r_b1u4", title:"De ce nu există o singură Românie", titleEn:"Why there is no single Romania", level:"b1_1", format:"article", wordCount:421,
  ro:"Cine vine în România pentru prima dată se așteaptă la o singură țară. În realitate, găsește mai multe.\n\nÎn Transilvania se vede imediat influența maghiară și germană: orașe cu piețe centrale, biserici fortificate, un ritm mai așezat. În Moldova, accentul este altul și oamenii îl recunosc după câteva cuvinte. În Dobrogea, lângă mare, au trăit împreună români, turci, tătari și greci, iar bucătăria arată asta.\n\nDiferențele nu sunt doar istorice. Un om din Cluj și unul din Constanța mănâncă altceva duminica, se salută puțin diferit și glumesc pe seama celuilalt fără răutate. Bucureștiul, ca orice capitală, atrage oameni din toate regiunile și amestecă totul.\n\nÎn Banat, lucrurile se fac altfel și localnicii țin să sublinieze asta. Timișoara a fost multă vreme un oraș în care se auzeau, pe aceeași stradă, româna, germana, maghiara și sârba, iar urmele se văd și azi în arhitectură și în felul în care oamenii se raportează la reguli. În Oltenia, dimpotrivă, veți auzi o vorbire mai rapidă și mai directă, cu verbe la perfectul simplu — „făcui”, „mersei” — pe care restul țării le folosește aproape numai în scris.\n\nChiar și mâncarea spune de unde vine cineva. Aceeași ciorbă se acrește cu borș în Moldova, cu zeamă de varză în Ardeal și cu oțet sau cu lămâie în sud. Sarmalele se fac în foi de varză aproape peste tot, dar lângă mare le veți găsi și în foi de viță. Nimeni nu crede că varianta lui este una dintre multe: fiecare este convins că a lui este cea normală.\n\nExistă și o diferență despre care se vorbește mai rar: cea dintre oraș și sat. Un tânăr din Cluj și unul din București se înțeleg imediat, chiar dacă vin din regiuni diferite, pentru că citesc aceleași lucruri și lucrează în domenii asemănătoare. Între același tânăr și bunicii lui de la țară, distanța poate fi mai mare decât între două regiuni.\n\nLa toate acestea se adaugă ceva mai nou. După anii 2000, milioane de români au plecat să lucreze în Italia, în Spania sau în Germania, iar mulți s-au întors, măcar pentru o vreme. Au adus cu ei cuvinte, obiceiuri și case construite după modele văzute afară. În unele sate veți auzi copii care se joacă în română și vorbesc la telefon cu bunicii în italiană.\n\nPentru cineva care învață limba, asta e o veste bună și una proastă. Vestea proastă: veți auzi variante pe care nu le găsiți în manual. Vestea bună: nimeni nu vă va corecta accentul, pentru că nu există unul singur pe care toți îl folosesc.",
  en:"Anyone coming to Romania for the first time expects a single country. In reality, they find several. In Transylvania the Hungarian and German influence is immediately visible: towns with central squares, fortified churches, a more settled rhythm. In Moldova the accent is different and people recognise it after a few words. In Dobrogea, by the sea, Romanians, Turks, Tatars and Greeks have lived together, and the cooking shows it. The differences are not only historical. Someone from Cluj and someone from Constanța eat something different on Sundays, greet each other slightly differently, and joke about one another without malice. Bucharest, like any capital, attracts people from every region and mixes everything together. In Banat things are done differently, and locals are keen to point that out. Timișoara was for a long time a city where Romanian, German, Hungarian and Serbian could be heard on the same street, and the traces are still visible today in the architecture and in how people relate to rules. In Oltenia, by contrast, you will hear a faster and more direct way of speaking, with verbs in the simple perfect — „făcui”, „mersei” — which the rest of the country uses almost only in writing. Even the food says where someone comes from. The same soup is soured with borș in Moldova, with cabbage brine in Ardeal, and with vinegar or lemon in the south. Sarmale are made in cabbage leaves almost everywhere, but near the sea you will also find them in vine leaves. Nobody thinks their version is one among many: each is convinced that theirs is the normal one. There is also a difference that gets discussed less: the one between town and village. A young person from Cluj and one from Bucharest understand each other immediately, even coming from different regions, because they read the same things and work in similar fields. Between that same young person and their grandparents in the countryside, the distance can be greater than between two regions. To all this something newer has been added. After the 2000s, millions of Romanians left to work in Italy, Spain or Germany, and many came back, at least for a while. They brought words, habits, and houses built to designs seen abroad. In some villages you will hear children playing in Romanian and talking on the phone to their grandparents in Italian. For someone learning the language, that is good news and bad news. The bad news: you will hear variants you will not find in the textbook. The good news: nobody will correct your accent, because there is no single one that everybody uses.",
  glossary:{"sublinieze":"to underline, to stress","se raportează":"they relate (to)","dimpotrivă":"on the contrary","se acrește":"is soured","zeamă de varză":"cabbage brine","foi de viță":"vine leaves","asemănătoare":"similar","obiceiuri":"customs, habits","măcar":"at least","se așteaptă":"expects","fortificate":"fortified","așezat":"settled, unhurried","recunosc":"they recognise","amestecă":"mixes","pe seama":"at the expense of","răutate":"malice","variante":"variants","manual":"textbook"}},

 {id:"r_b1u6", title:"Ghid: certificatul de rezidență", titleEn:"Guide: the residence certificate", level:"b1_1", format:"official guide", wordCount:419,
  ro:"CERTIFICAT DE ÎNREGISTRARE PENTRU CETĂȚENII UE\n\nCine depune: cetățenii Uniunii Europene care rămân în România mai mult de nouăzeci de zile.\n\nActe necesare:\n— cerere tip, completată și semnată;\n— document de identitate, în original și copie;\n— dovada scopului șederii (contract de muncă, adeverință de student sau dovada unor mijloace de întreținere);\n— dovada spațiului de locuit, cu ștampila proprietarului.\n\nUnde: la Inspectoratul General pentru Imigrări din județul unde locuiți.\n\nTermen: cererea se depune înainte de expirarea celor nouăzeci de zile. Certificatul se eliberează, de regulă, în termen de treizeci de zile de la depunerea unui dosar complet.\n\nTaxe: pentru cetățenii Uniunii Europene, procedura nu presupune o taxă de analiză a dosarului. Verificați totuși pe site dacă se percepe contravaloarea documentului, pentru că acest lucru se poate modifica de la un an la următorul.\n\nMembrii de familie: soțul sau soția și copiii depun dosare separate, chiar dacă vin în același timp. Membrii de familie care nu sunt cetățeni ai Uniunii Europene primesc alt tip de document și au nevoie, în plus, de dovada legăturii de rudenie, tradusă și legalizată.\n\nDacă vă schimbați adresa: orice mutare în altă localitate se anunță la formațiunea teritorială de imigrări de la noul domiciliu. Certificatul rămâne valabil, dar datele din dosar trebuie actualizate.\n\nDupă cinci ani: cetățenii Uniunii Europene care au locuit legal și neîntrerupt în România timp de cinci ani pot solicita dreptul de rezidență permanentă. Absențele scurte nu întrerup această perioadă.\n\nCât durează în practică: termenul legal este de treizeci de zile, însă în perioadele aglomerate — toamna, când vin studenții — se poate ajunge la mai mult. Nu plecați din țară în această perioadă fără să întrebați dacă vă puteți ridica documentul mai târziu.\n\nCe nu este certificatul: certificatul de înregistrare nu este act de identitate. Nu înlocuiește pașaportul sau cartea de identitate din țara de origine și nu vă scutește de obligația de a le avea asupra dumneavoastră.\n\nGreșeli frecvente: cele mai multe dosare se întorc pentru că lipsește dovada spațiului de locuit sau pentru că aceasta este pe numele altcuiva, fără acordul proprietarului. A doua cauză este cererea completată cu date care nu corespund celor din documentul de identitate.\n\nProgramare: la unele formațiuni teritoriale depunerea se face numai pe bază de programare online, iar locurile se ocupă cu câteva săptămâni înainte. Faceți programarea din prima lună de ședere, chiar dacă nu aveți încă toate actele, pentru că data programării nu depinde de dosar.\n\nAtenție: dosarele incomplete nu se înregistrează. Verificați lista de acte pe site înainte de a veni, pentru că se modifică periodic.",
  en:"REGISTRATION CERTIFICATE FOR EU CITIZENS. Who applies: citizens of the European Union who stay in Romania for more than ninety days. Documents required: standard application form, completed and signed; identity document, original and copy; proof of the purpose of the stay (employment contract, student certificate, or proof of means of support); proof of accommodation, with the owner's stamp. Where: at the General Inspectorate for Immigration in the county where you live. Deadline: the application is submitted before the ninety days expire. The certificate is issued, as a rule, within thirty days of a complete file being submitted. Fees: for EU citizens the procedure does not involve a file-processing fee. Check on the website anyway whether the cost of the document itself is charged, as this can change from one year to the next. Family members: a spouse and children submit separate files, even if they arrive at the same time. Family members who are not EU citizens receive a different type of document and additionally need proof of the family relationship, translated and legalised. If you change your address: any move to another locality must be reported to the territorial immigration office at the new address. The certificate remains valid, but the file must be updated. After five years: EU citizens who have lived legally and continuously in Romania for five years may apply for the right of permanent residence. Short absences do not interrupt this period. How long it takes in practice: the legal deadline is thirty days, but in busy periods — autumn, when the students arrive — it can take longer. Do not leave the country during this period without asking whether you can collect the document later. What the certificate is not: the registration certificate is not an identity document. It does not replace the passport or identity card from your country of origin, and does not exempt you from the obligation to carry them. Common mistakes: most files are returned because proof of accommodation is missing, or because it is in someone else's name without the owner's consent. The second cause is an application completed with details that do not match those in the identity document. Appointments: at some territorial offices, applications are only accepted by online appointment, and the slots fill up several weeks in advance. Make the appointment in your first month of residence, even if you do not yet have all the documents, because the appointment date does not depend on the file. Attention: incomplete files are not registered. Check the list of documents on the website before you come, as it is amended periodically.",
  glossary:{"se percepe":"is charged, is levied","contravaloarea":"the value, the cost (of)","legăturii de rudenie":"of the family relationship","legalizată":"notarised, legalised","formațiunea teritorială":"the territorial office","domiciliu":"place of residence","neîntrerupt":"uninterrupted","solicita":"to request, to apply for","aglomerate":"busy, crowded","vă scutește":"exempts you","asupra dumneavoastră":"on your person","acordul":"the consent","corespund":"they correspond, they match","depune":"submits","șederii":"of the stay","adeverință":"official certificate","mijloace de întreținere":"means of support","spațiului de locuit":"of the living space","județul":"the county","de regulă":"as a rule","expirarea":"the expiry","se modifică":"is changed","periodic":"periodically"}},

 {id:"r_b1_2u2", title:"Trei știri scurte", titleEn:"Three short news items", level:"b1_2", format:"news", wordCount:403,
  ro:"TRANSPORT. Potrivit primăriei, lucrările de pe bulevardul principal se vor încheia până la sfârșitul lunii. Traficul a fost deviat pe străzile laterale, iar șoferii sunt sfătuiți să evite zona între orele șapte și nouă dimineața. Lucrările au început în primăvară și au fost întrerupte de două ori din cauza vremii. Un reprezentant al constructorului a explicat că stratul de asfalt se toarnă numai peste o anumită temperatură, motiv pentru care lucrările nu pot fi grăbite oricând. Primăria susține că întârzierea nu va duce la costuri suplimentare, pentru că termenul a fost prevăzut în contract. Locuitorii din zonă se plâng însă de praf și de zgomot, iar comercianții de pe bulevard spun că au pierdut clienți în ultimele luni. Până la finalizarea marcajelor, circulația se va face pe o singură bandă pe sens.\n\nMEDIU. Un studiu publicat marți arată că nivelul de poluare din marile orașe a scăzut ușor față de anul trecut. Autorii precizează însă că scăderea se datorează mai ales vremii, nu unor măsuri noi. „Nu putem vorbi despre o îmbunătățire reală”, a declarat unul dintre cercetători. Studiul a analizat datele din șase orașe, pe parcursul a doi ani. Cea mai mare scădere a fost înregistrată iarna, în lunile cu vânt puternic, ceea ce susține concluzia autorilor. Un alt cercetător, care nu a participat la studiu, a atras atenția că măsurătorile se fac în puține puncte din oraș și că valorile pot fi mult mai mari lângă marile bulevarde. Organizațiile de mediu cer măsuri concrete: transport public mai bun, restricții pentru mașinile vechi și mai multe spații verzi. Ministerul nu a comentat până la închiderea ediției.\n\nEDUCAȚIE. Ministerul a anunțat că examenele naționale se vor desfășura în aceeași perioadă ca anul trecut. Sindicatele au cerut clarificări privind organizarea, întrucât în unele județe lipsesc profesori. Potrivit datelor publicate anul trecut, în unele județe din nordul țării lipsesc peste o sută de profesori, mai ales de matematică și de limbi străine. Sindicatele cer ca posturile să fie ocupate înainte de începerea examenelor, nu în timpul lor. În paralel, ministerul a anunțat un program de burse pentru studenții care se pregătesc să devină profesori și acceptă să predea, după absolvire, în localități mici. Părinții au reacționat pe rețelele sociale, iar câteva asociații au anunțat că vor cere o întâlnire cu ministrul. Calendarul detaliat, cu datele fiecărei probe, urmează să fie publicat în Monitorul Oficial. Reprezentanții ministerului au spus că vor răspunde în cursul săptămânii viitoare.",
  en:"TRANSPORT. According to the city hall, the works on the main boulevard will be finished by the end of the month. Traffic has been diverted onto the side streets, and drivers are advised to avoid the area between seven and nine in the morning. The works began in spring and were interrupted twice because of the weather. A representative of the contractor explained that the asphalt layer is only poured above a certain temperature, which is why the works cannot be hurried at any time. The city hall maintains that the delay will not lead to additional costs, because the deadline was provided for in the contract. Residents of the area, however, complain about dust and noise, and traders on the boulevard say they have lost customers in recent months. Until the road markings are finished, traffic will run in a single lane in each direction. ENVIRONMENT. A study published on Tuesday shows that the level of pollution in the big cities has fallen slightly compared with last year. The authors point out, however, that the drop is mainly due to the weather rather than to any new measures. \"We cannot speak of a real improvement,\" one of the researchers said. The study analysed data from six cities over two years. The largest drop was recorded in winter, in the windy months, which supports the authors' conclusion. Another researcher, who did not take part in the study, pointed out that measurements are taken at few points in the city and that the values can be much higher next to the big boulevards. Environmental organisations are calling for concrete measures: better public transport, restrictions on old cars, and more green space. The ministry had not commented by the time the edition closed. EDUCATION. The ministry has announced that the national exams will take place in the same period as last year. The unions have asked for clarification about the arrangements, since teachers are missing in some counties. According to figures published last year, in some counties in the north of the country more than a hundred teachers are missing, above all in mathematics and foreign languages. The unions are asking for the posts to be filled before the exams begin, not during them. In parallel, the ministry has announced a scholarship programme for students training to become teachers who agree to teach, after graduating, in small localities. Parents have reacted on social media, and several associations have announced that they will request a meeting with the minister. The detailed calendar, with the dates of each paper, is due to be published in the Official Gazette. Representatives of the ministry said they would respond in the course of next week.",
  glossary:{"întrerupte":"interrupted","stratul":"the layer","se toarnă":"is poured","grăbite":"hurried, rushed","întârzierea":"the delay","suplimentare":"additional","comercianții":"the traders, the shopkeepers","marcajelor":"of the road markings","pe parcursul":"over the course of","a atras atenția":"pointed out, drew attention","măsurătorile":"the measurements","posturile":"the posts, the positions","burse":"scholarships","absolvire":"graduation","lucrările":"the works","deviat":"diverted","sfătuiți":"advised","studiu":"study","a scăzut":"has fallen","precizează":"specify","se datorează":"is due to","măsuri":"measures","cercetători":"researchers","se vor desfășura":"will take place","sindicatele":"the unions","clarificări":"clarifications","privind":"regarding","în cursul":"in the course of"}},

 {id:"r_b1_2u6", title:"Ziua în care am plecat", titleEn:"The day I left", level:"b1_2", format:"memoir", wordCount:409,
  ro:"Aveam nouăsprezece ani când am plecat prima dată de acasă. Până atunci nu dormisem niciodată singur într-un alt oraș.\n\nÎmi amintesc dimineața aceea foarte clar. Mama pregătise mâncare pentru drum, deși știa că era doar o oră cu trenul. Tata nu spusese nimic toată dimineața, iar eu crezusem că e supărat. Abia mai târziu mi-am dat seama că, de fapt, nu știa ce să spună.\n\nDupă ce am urcat în tren, m-am așezat lângă fereastră și am simțit ceva ciudat: nu era tristețe, era mai degrabă o liniște pe care nu o mai avusesem până atunci.\n\nDrumul a durat exact cincizeci și cinci de minute, dar mi s-a părut mult mai lung. Mă uitam pe geam la satele pe lângă care trecusem de zeci de ori cu mașina și care acum arătau altfel, pentru că știam că nu mă întorc seara. La un moment dat am deschis punga cu mâncare, deși nu îmi era foame, doar ca să fac ceva cu mâinile.\n\nCamera în care m-am mutat avea un pat, un dulap și o fereastră care dădea într-o curte interioară. Îmi promisesem că o să o aranjez în prima săptămână, dar am lăsat cutiile nedespachetate aproape o lună. Colegul de cameră venise cu o zi înainte și își pusese deja pozele pe perete. Mi-a fost rușine să recunosc că nu adusesem nicio poză.\n\nPrimele zile au fost o serie de lucruri mici pe care nu le făcusem niciodată singur: să întreb la ghișeu, să îmi cumpăr abonament, să gătesc altceva decât ouă. Nimic dificil, luat separat. Împreună însă, obosesc. Am ținut minte și mirosul scării blocului, care nu semăna cu niciunul de acasă, și zgomotul tramvaiului care trecea pe la șase dimineața și pe care, după o lună, nu îl mai auzeam deloc, deși trecea la fel de zgomotos ca în prima seară.\n\nÎn primele săptămâni am sunat acasă în fiecare seară. Apoi din ce în ce mai rar, nu pentru că nu îmi lipseau, ci pentru că începusem să am viața mea acolo.\n\nAm învățat și ceva ce nu mă așteptam: că dorul nu vine când te aștepți. Nu mi-a fost dor acasă în prima seară, ci după trei săptămâni, într-o marți banală, când am simțit mirosul de mâncare de la o fereastră deschisă și mi-am dat seama că nu mai mâncasem de mult ceva gătit de mama.\n\nAcum, când mă întorc în orașul acela, îmi dau seama cât de mic era. Pe atunci mi se părea imens.",
  en:"I was nineteen when I first left home. Until then I had never slept alone in another city. I remember that morning very clearly. My mother had prepared food for the journey, although she knew it was only an hour by train. My father had said nothing all morning, and I had thought he was upset. Only later did I realise that in fact he did not know what to say. After I got on the train, I sat down by the window and felt something strange: it was not sadness, it was rather a calm I had never had before. The journey took exactly fifty-five minutes, but it felt much longer. I looked out at the villages I had driven past dozens of times, which now looked different, because I knew I was not coming back that evening. At some point I opened the bag of food, although I was not hungry, just to do something with my hands. The room I moved into had a bed, a wardrobe and a window that looked onto an inner courtyard. I had promised myself I would arrange it in the first week, but I left the boxes unpacked for almost a month. My roommate had arrived a day earlier and had already put his photos on the wall. I was ashamed to admit that I had not brought a single photo. The first days were a series of small things I had never done alone: asking at a counter, buying myself a travel pass, cooking something other than eggs. Nothing difficult, taken separately. Together, though, they wear you out. I also remember the smell of the stairwell, which was like no other from home, and the noise of the tram that went past at six in the morning and which, after a month, I no longer heard at all, although it went past just as noisily as on the first evening. In the first weeks I called home every evening. Then less and less often, not because I did not miss them, but because I had started to have my own life there. I also learned something I had not expected: that homesickness does not come when you expect it. I was not homesick on the first evening, but after three weeks, on an ordinary Tuesday, when I smelled food from an open window and realised that it had been a long time since I had eaten anything my mother had cooked. Now, when I go back to that city, I realise how small it was. Back then it seemed enormous to me.",
  glossary:{"trecusem":"I had passed (pluperfect)","la un moment dat":"at one point","dădea într-o curte":"looked onto a courtyard","îmi promisesem":"I had promised myself","nedespachetate":"unpacked","venise":"he had arrived (pluperfect)","își pusese":"he had put (pluperfect)","mi-a fost rușine":"I was ashamed","adusesem":"I had brought (pluperfect)","ghișeu":"counter, service window","abonament":"season ticket, travel pass","dorul":"longing, homesickness","banală":"ordinary, unremarkable","mâncasem":"I had eaten (pluperfect)","pregătise":"had prepared","spusese":"had said","crezusem":"I had thought","mi-am dat seama":"I realised","de fapt":"in fact","m-am așezat":"I sat down","tristețe":"sadness","mai degrabă":"rather","liniște":"calm","avusesem":"I had had","din ce în ce mai rar":"less and less often","îmi lipseau":"I missed them","începusem":"I had begun","imens":"immense"}},

 /* Written for this course at the difficulty the ILR reading paper actually
    uses — an opinion piece with an argument that turns, which is harder than
    the informational texts a general B1 course tends to set. */
 {id:"r_ilr_lectura", title:"De ce uităm ce citim", titleEn:"Why we forget what we read", level:"ilr", format:"opinion piece", wordCount:234,
  ro:"Mulți dintre noi ne plângem că uităm cărțile pe care le-am citit. Ne amintim că ne-a plăcut un roman, dar nu mai știm nici numele personajelor. Concluzia pare evidentă: memoria noastră s-a stricat, probabil din cauza telefoanelor.\n\nMi se pare că lucrurile stau altfel. Am uitat întotdeauna aproape tot ce am citit — diferența e că acum ne dăm seama, pentru că avem unde să verificăm.\n\nÎnainte, o carte citită rămânea o amintire vagă și nimeni nu ne cerea socoteală. Astăzi, în două secunde găsim rezumatul și vedem cât de puțin am reținut. Sentimentul de pierdere e nou; pierderea în sine, nu.\n\nMai mult, cred că uitarea nu este un defect al lecturii, ci o parte din ea. Ceea ce rămâne după ce am uitat subiectul nu e nimic: e felul în care cartea ne-a schimbat, discret, modul de a privi lumea. Un cititor care a trecut prin cincizeci de romane gândește altfel decât unul care n-a citit niciunul, chiar dacă niciunul dintre ei nu poate rezuma corect cele cincizeci de cărți.\n\nDesigur, există și o lectură care cere memorare: un manual, un contract, un articol de specialitate. Dar a citi literatură ca pe un manual, cu teama că vei fi examinat, e cel mai sigur mod de a nu înțelege nimic.\n\nAșadar, dacă ați uitat romanul de anul trecut, nu vă îngrijorați. Probabil că el nu a plecat nicăieri.",
  en:"Many of us complain that we forget the books we have read. We remember that we liked a novel, but we no longer know even the characters' names. The conclusion seems obvious: our memory has broken down, probably because of phones. It seems to me that things are otherwise. We have always forgotten almost everything we read — the difference is that now we notice, because we have somewhere to check. Before, a book you had read remained a vague memory and nobody called you to account. Today, in two seconds we find the summary and see how little we retained. The feeling of loss is new; the loss itself is not. What is more, I think forgetting is not a defect of reading but a part of it. What remains after we have forgotten the plot is not nothing: it is the way the book quietly changed how we see the world. A reader who has been through fifty novels thinks differently from one who has read none, even if neither of them can correctly summarise the fifty books. Of course, there is also reading that demands memorisation: a textbook, a contract, a specialist article. But reading literature as though it were a textbook, afraid you will be examined, is the surest way to understand nothing. So if you have forgotten last year's novel, do not worry. It has probably not gone anywhere.",
  glossary:{"ne plângem":"we complain","evidentă":"obvious","s-a stricat":"has broken down","stau altfel":"are otherwise","ne cerea socoteală":"called us to account","rezumatul":"the summary","am reținut":"we retained","pierderea":"the loss","uitarea":"forgetting","defect":"defect","discret":"quietly, discreetly","a rezuma":"to summarise","de specialitate":"specialist","teama":"the fear","așadar":"so, therefore"}},

 /* Held back for the mock exam so the simulation is not sat on material the
    learner has already worked through. Same difficulty and same shape as the
    unit text: an argument that turns, with concessions to trip A/F items. */
 {id:"r_ilr_mock", title:"Orașul care nu doarme niciodată — și de ce ar trebui", titleEn:"The city that never sleeps — and why it should", level:"ilr", format:"opinion piece", wordCount:234,
  ro:"Se spune adesea că un oraș bun este un oraș care nu se oprește. Magazine deschise la miezul nopții, transport la orice oră, cafenele pline la ora două dimineața. Multă lume consideră acest lucru un semn de civilizație.\n\nEu cred că am confundat două lucruri diferite: disponibilitatea și viața.\n\nEste adevărat că un oraș în care totul se închide la ora șase devine, pentru cine lucrează târziu, aproape de nelocuit. Nimeni nu susține că trebuie să ne întoarcem acolo. Însă între a putea cumpăra lapte la ora unsprezece și a construi o economie care cere ca cineva să stea treaz toată noaptea pentru comoditatea altcuiva există o distanță considerabilă.\n\nÎn ultimii ani, orașele mari din România au început să semene tot mai mult cu acest model. Curieri care livrează până dimineața, farmacii non-stop, birouri în care lumina rămâne aprinsă la miezul nopții. Se vorbește despre asta ca despre un progres.\n\nCei care lucrează noaptea, însă, spun altceva. Studiile arată de mult că munca de noapte afectează somnul, inima și starea psihică. Iar cei mai mulți dintre acești oameni nu au ales programul; l-au acceptat pentru că nu aveau alternativă.\n\nDesigur, unele servicii trebuie să funcționeze permanent: spitalele, pompierii, transportul de urgență. Nimeni nu discută asta.\n\nÎntrebarea nu este dacă orașul trebuie să fie viu, ci cine plătește pentru ca el să pară astfel. De obicei, nu cei care se bucură de comoditate.",
  en:"It is often said that a good city is a city that does not stop. Shops open at midnight, transport at any hour, cafés full at two in the morning. Many people consider this a sign of civilisation. I think we have confused two different things: availability and life. It is true that a city in which everything closes at six becomes, for someone who works late, almost uninhabitable. Nobody is arguing that we should go back to that. But between being able to buy milk at eleven and building an economy that requires someone to stay awake all night for someone else's convenience there is a considerable distance. In recent years, the big cities in Romania have begun to resemble this model more and more. Couriers delivering until morning, all-night pharmacies, offices where the light stays on at midnight. This is spoken of as progress. Those who work at night, however, say something else. Studies have long shown that night work affects sleep, the heart and mental health. And most of these people did not choose the schedule; they accepted it because they had no alternative. Of course, some services must operate permanently: hospitals, firefighters, emergency transport. Nobody disputes that. The question is not whether the city should be alive, but who pays for it to appear that way. Usually, not those who enjoy the convenience.",
  glossary:{"disponibilitatea":"availability","de nelocuit":"uninhabitable","susține":"argues, maintains","comoditatea":"the convenience","considerabilă":"considerable","curieri":"couriers","livrează":"deliver","aprinsă":"lit, switched on","progres":"progress","afectează":"affects","starea psihică":"mental state","alternativă":"alternative","permanent":"permanently","pompierii":"the firefighters","nu discută":"does not dispute","să pară":"to seem"}},

 /* ---------- A2.2 ----------
    Sits between A2.1 (112–134 words) and B1, so these run 150–185: longer
    paragraphs, more connectives, and the first texts where the reader has to
    hold two competing positions in mind at once. */
 {id:"r_a2_2u1", title:"Două oferte de telefon", titleEn:"Two phone deals", level:"a2_2", format:"comparison", wordCount:149,
  ro:"Vreau să îmi schimb abonamentul la telefon și am găsit două oferte.\n\nPrima costă treizeci și cinci de lei pe lună. Include nelimitat în țară, cincizeci de gigabytes de internet și zece euro credit pentru străinătate. Contractul este pe doi ani.\n\nA doua costă patruzeci și cinci de lei, deci este mai scumpă. În schimb, are internet nelimitat și contractul este doar pe un an. Include și un abonament la o platformă de filme.\n\nLa prima vedere, prima ofertă pare mai bună, pentru că este mai ieftină. Dar eu folosesc telefonul foarte mult, mai ales când călătoresc, și cincizeci de gigabytes nu îmi ajung niciodată. Luna trecută am plătit în plus douăzeci de lei pentru trafic suplimentar.\n\nAșadar, a doua ofertă este mai scumpă pe hârtie, dar pentru mine iese mai ieftină. Contractul mai scurt este la fel de important: peste un an poate apare ceva și mai bun.",
  en:"I want to change my phone plan and I have found two offers. The first costs thirty-five lei a month. It includes unlimited calls within the country, fifty gigabytes of internet and ten euros of credit for abroad. The contract is for two years. The second costs forty-five lei, so it is more expensive. On the other hand, it has unlimited internet and the contract is only for one year. It also includes a subscription to a film platform. At first sight the first offer seems better, because it is cheaper. But I use my phone a great deal, especially when I travel, and fifty gigabytes are never enough for me. Last month I paid an extra twenty lei for additional data. So the second offer is more expensive on paper, but for me it works out cheaper. The shorter contract matters just as much: in a year's time something even better may come along.",
  glossary:{"abonamentul":"the subscription, the plan","nelimitat":"unlimited","în schimb":"on the other hand","la prima vedere":"at first sight","nu îmi ajung":"are not enough for me","în plus":"extra, in addition","trafic suplimentar":"additional data","pe hârtie":"on paper","iese mai ieftină":"works out cheaper","poate apare":"something may come along"}},

 {id:"r_a2_2u3", title:"O reclamație și răspunsul ei", titleEn:"A complaint and its reply", level:"a2_2", format:"email exchange", wordCount:129,
  ro:"Stimată doamnă,\n\nAm cumpărat de la magazinul dumneavoastră o mașină de cafea, pe data de 3 martie. După două săptămâni, aparatul a început să facă un zgomot puternic și acum nu mai pornește deloc.\n\nAm bonul fiscal și garanția. Aș dori să îl înlocuiți sau să îmi returnați banii.\n\nCu stimă,\nRadu Marin\n\n———\n\nStimate domnule Marin,\n\nVă mulțumim pentru mesaj și ne pare rău pentru situația creată.\n\nConform legii, aveți dreptul la reparație, înlocuire sau restituirea banilor. Pentru că produsul are mai puțin de o lună, vă propunem înlocuirea cu un aparat nou.\n\nVă rugăm să veniți la magazin cu bonul și cu aparatul în ambalajul original, dacă îl mai aveți. Dacă nu, nu este o problemă.\n\nÎnlocuirea se face pe loc, în aproximativ cincisprezece minute.\n\nCu stimă,\nServiciul Clienți",
  en:"Dear Madam, I bought a coffee machine from your shop on 3 March. After two weeks the appliance started making a loud noise and now it does not switch on at all. I have the receipt and the warranty. I would like you to replace it or refund my money. Yours sincerely, Radu Marin. — Dear Mr Marin, Thank you for your message and we are sorry for the situation. Under the law you are entitled to repair, replacement or a refund. Because the product is less than a month old, we propose replacing it with a new appliance. Please come to the shop with the receipt and with the appliance in its original packaging, if you still have it. If not, that is not a problem. The replacement is done on the spot, in about fifteen minutes. Yours sincerely, Customer Service.",
  glossary:{"aparatul":"the appliance","zgomot":"noise","bonul fiscal":"the till receipt","garanția":"the warranty","să îl înlocuiți":"that you replace it","să îmi returnați":"that you refund me","Conform legii":"under the law","restituirea banilor":"a refund","ambalajul":"the packaging","pe loc":"on the spot"}},

 {id:"r_a2_2u4", title:"Mărțișorul", titleEn:"The mărțișor", level:"a2_2", format:"cultural article", wordCount:139,
  ro:"Pe 1 martie, în România, bărbații le oferă femeilor un mărțișor. Este un obiect mic, legat cu un șnur roșu și alb, care se prinde de haină și se poartă toată luna.\n\nRoșul înseamnă viață și sănătate, iar albul înseamnă curățenie și început nou. Împreună, ele anunță primăvara.\n\nObiceiul nu este nou. Se crede că vine din vremuri foarte vechi, dinainte de creștinism, și se găsește și în Bulgaria, unde se numește altfel.\n\nAstăzi, mărțișorul se cumpără din piețe și de la standuri care apar peste tot în ultima săptămână din februarie. Copiii le dau mărțișoare învățătoarelor, colegii de birou și le dau între ei, iar florile — de obicei ghiocei — merg împreună cu el.\n\nPentru un străin, cel mai surprinzător lucru nu este obiectul, ci cât de serios este luat. Pe 1 martie, o femeie care nu primește nimic observă imediat.",
  en:"On 1 March in Romania, men give women a mărțișor. It is a small object tied with a red and white string, which is pinned to a coat and worn all month. Red means life and health, and white means purity and a new beginning. Together they announce spring. The custom is not new. It is believed to come from very ancient times, before Christianity, and it is also found in Bulgaria, where it has a different name. Today mărțișoare are bought at markets and from stalls that appear everywhere in the last week of February. Children give them to their teachers, office colleagues give them to each other, and flowers — usually snowdrops — go with them. For a foreigner the most surprising thing is not the object but how seriously it is taken. On 1 March, a woman who receives nothing notices immediately.",
  glossary:{"le oferă":"give (to them)","șnur":"string, cord","se prinde":"is pinned","curățenie":"purity, cleanliness","anunță":"announce","Obiceiul":"the custom","vremuri":"times","creștinism":"Christianity","standuri":"stalls","învățătoarelor":"to the (primary) teachers","ghiocei":"snowdrops","cât de serios":"how seriously"}},

 {id:"r_a2_2u6", title:"Reguli pentru locatari", titleEn:"Rules for residents", level:"a2_2", format:"notice", wordCount:112,
  ro:"ASOCIAȚIA DE PROPRIETARI — REGULAMENT\n\nLiniștea. Între orele 22:00 și 7:00, precum și între 13:00 și 15:00, nu faceți zgomot. Nu folosiți mașini de găurit și nu dați muzica tare.\n\nGunoiul. Aruncați gunoiul numai în containerele din spatele blocului. Nu lăsați saci pe scară, nici măcar pentru câteva ore.\n\nLiftul. Copiii sub zece ani nu au voie să folosească liftul singuri. Este interzis să transportați mobilă fără să anunțați administratorul.\n\nAnimalele. Câinii trebuie ținuți în lesă pe scară și în curte. Proprietarii sunt obligați să curețe după ei.\n\nParcarea. Fiecare apartament are un singur loc. Nu parcați pe locul altcuiva, chiar dacă mașina lipsește de câteva zile.\n\nPentru orice problemă, scrieți administratorului. Nu lăsați bilete pe uși.",
  en:"OWNERS' ASSOCIATION — RULES. Quiet. Between 10 p.m. and 7 a.m., and also between 1 p.m. and 3 p.m., do not make noise. Do not use drills and do not play music loudly. Rubbish. Throw rubbish only into the containers behind the building. Do not leave bags in the stairwell, not even for a few hours. The lift. Children under ten are not allowed to use the lift alone. It is forbidden to transport furniture without informing the administrator. Animals. Dogs must be kept on a lead in the stairwell and in the courtyard. Owners are obliged to clean up after them. Parking. Each flat has a single space. Do not park in someone else's space, even if the car has been missing for several days. For any problem, write to the administrator. Do not leave notes on doors.",
  glossary:{"locatari":"residents","Regulament":"rules, regulations","mașini de găurit":"drills","Gunoiul":"the rubbish","saci":"bags","scară":"stairwell","nu au voie":"are not allowed","Este interzis":"it is forbidden","administratorul":"the building administrator","lesă":"lead, leash","sunt obligați":"are obliged","altcuiva":"someone else's","bilete":"notes"}},

 {id:"r_a2_2u7", title:"Cum se trăia la bunici", titleEn:"How life was at my grandparents'", level:"a2_2", format:"memoir", wordCount:152,
  ro:"Când eram mică, îmi petreceam toate verile la bunici, la țară.\n\nCasa nu avea apă curentă. În fiecare dimineață, bunicul mergea la fântână cu două găleți și eu mergeam după el, deși nu puteam să car nimic. Bunica făcea pâine o dată pe săptămână, într-un cuptor de afară, și mirosul se simțea din capătul străzii.\n\nNu aveam televizor. Seara stăteam în curte și vecinii veneau să vorbească. Nimeni nu suna înainte; pur și simplu apăreau.\n\nÎntr-o vară, când aveam nouă ani, s-a stricat cuptorul. Bunica a fost supărată două zile. Apoi a hotărât că nu are rost să aștepte și a început să facă pâinea la vecina de peste drum. Timp de trei luni, în fiecare joi, mergeam împreună cu aluatul într-un lighean acoperit cu un prosop.\n\nAcum casa are apă curentă și un cuptor nou. Bunica nu mai face pâine. Spune că nu mai are pentru cine.",
  en:"When I was little, I used to spend all my summers at my grandparents' in the countryside. The house had no running water. Every morning my grandfather went to the well with two buckets and I went after him, although I could not carry anything. My grandmother made bread once a week, in an outdoor oven, and you could smell it from the end of the street. We had no television. In the evening we sat in the yard and the neighbours came to talk. Nobody phoned first; they simply appeared. One summer, when I was nine, the oven broke. My grandmother was upset for two days. Then she decided there was no point waiting and started making the bread at the neighbour's across the road. For three months, every Thursday, we went together with the dough in a basin covered with a towel. Now the house has running water and a new oven. My grandmother does not make bread any more. She says she has no one to make it for.",
  glossary:{"îmi petreceam":"I used to spend","apă curentă":"running water","fântână":"well","găleți":"buckets","car":"carry","cuptor":"oven","mirosul":"the smell","din capătul":"from the end of","pur și simplu":"simply","s-a stricat":"broke down","nu are rost":"there is no point","aluatul":"the dough","lighean":"basin","prosop":"towel","pentru cine":"for whom"}},

 /* ---------- REGISTER TRACK ----------
    The point of this track is what people actually write, so these are a chat
    log and a forum thread rather than prose. The chat is deliberately printed
    without diacritics, because that is how it arrives on a phone and reading it
    is a skill of its own. */
 {id:"r_reg_chat", title:"Conversație pe telefon", titleEn:"A phone conversation", level:"register", format:"chat log", wordCount:106,
  ro:"— baa esti liber diseara?\n— pai depinde, la ce ora\n— pe la 8? vreau sa ies undeva ca am stat toata ziua in casa\n— nasol. da hai, merg\n— super. unde vrei?\n— mi-e egal sincer. numai sa nu fie locul ala de data trecuta, era prea scump si mancarea era praf\n— hahaha ok ok am inteles\n— zi si tu ceva\n— e un loc nou langa parc, se zice ca e misto. n-am fost inca\n— hai sa incercam atunci\n— bine. ne vedem acolo la 8 sau vii sa ma iei?\n— vin eu, oricum trec pe acolo\n— perfect. bagi si tu un mesaj cand pleci\n— da da. pe curand\n— pa",
  en:"— hey are you free tonight? — well it depends, what time — around 8? I want to go out somewhere because I've been indoors all day — rough. but come on, I'll go — great. where do you want? — I honestly don't mind. just not that place from last time, it was too expensive and the food was rubbish — hahaha ok ok got it — say something yourself — there's a new place near the park, they say it's cool. I haven't been yet — let's try it then — fine. shall we meet there at 8 or are you coming to get me? — I'll come, I'm passing that way anyway — perfect. drop me a message when you leave — yes yes. see you soon — bye",
  glossary:{"baa":"hey (very informal, from 'bă')","pai":"well (păi)","nasol":"rough, bad (slang)","hai":"come on","mi-e egal":"I don't mind","praf":"rubbish, terrible (lit. dust)","zi si tu ceva":"say something yourself","se zice":"they say","misto":"cool, nice (slang)","bagi un mesaj":"drop a message (slang)","pe curand":"see you soon","pa":"bye"}},

 {id:"r_reg_forum", title:"Discuție pe forum: chirii în București", titleEn:"Forum thread: rents in Bucharest", level:"register", format:"forum thread", wordCount:128,
  ro:"anonim_23: Băieți, m-am săturat. Caut de o lună garsonieră decentă sub 400 de euro și nu găsesc nimic. Ori e o gaură, ori e la naiba în praznic.\n\nmihai_b: Păi da, așa e piața acum. Acum doi ani găseai, acum nu mai găsești. Ai încercat prin Militari?\n\nanonim_23: Am fost la trei. Una avea mucegai pe perete și tipul se făcea că nu vede.\n\nelena.p: Sfat de la cineva care a trecut prin asta: nu te uita doar la chirie. Întreabă de întreținere. Iarna poate să ajungă la 400-500 de lei și te trezești că plătești mult mai mult decât credeai.\n\nmihai_b: +1. Și cere să vezi ultima factură, nu ce zice proprietarul.\n\nanonim_23: Bun, asta chiar ajută. Mersi.\n\nelena.p: Baftă. O să găsești, dar durează.",
  en:"anonim_23: Guys, I've had enough. I've been looking for a decent studio under 400 euros for a month and I can't find anything. Either it's a dump, or it's in the middle of nowhere. mihai_b: Well yes, that's the market now. Two years ago you'd find something, now you don't. Have you tried around Militari? anonim_23: I've been to three. One had mould on the wall and the guy pretended not to see it. elena.p: Advice from someone who's been through this: don't look only at the rent. Ask about the maintenance charge. In winter it can reach 400-500 lei and you find yourself paying much more than you thought. mihai_b: +1. And ask to see the last bill, not what the landlord says. anonim_23: Right, that actually helps. Thanks. elena.p: Good luck. You'll find something, but it takes time.",
  glossary:{"m-am săturat":"I've had enough","garsonieră":"studio flat","o gaură":"a dump (lit. a hole)","la naiba în praznic":"in the middle of nowhere (idiom)","piața":"the market","mucegai":"mould","se făcea că nu vede":"pretended not to see","a trecut prin asta":"has been through this","întreținere":"maintenance charge","te trezești că":"you find yourself (suddenly realising)","factură":"bill","Mersi":"thanks (informal)","Baftă":"good luck (informal)"}},

 /* ---------- B1 LONG FORM ----------
    The short B1 texts above are lesson-sized. These are the ones that build
    stamina: 420–470 words, several paragraphs, an argument that turns at least
    once, and no glossary coverage of the easy words. Reading a 450-word text
    without stopping is a different skill from reading three 150-word ones, and
    it is the skill the level exam and the I.L.R. paper actually test. */
 {id:"r_b1_long_munca", title:"Meseria pe care nu am ales-o", titleEn:"The job I did not choose", level:"b1_1", format:"personal essay", wordCount:617,
  ro:"La douăzeci și doi de ani credeam că știu exact ce vreau. Terminasem construcțiile, aveam o diplomă frumoasă într-un dosar de plastic și un tată care o arăta vecinilor. „Inginer”, spunea el, apăsând pe fiecare silabă, de parcă ar fi fost un titlu nobiliar.\n\nPrimul birou în care am lucrat avea ferestre care nu se deschideau și un aparat de aer condiționat pe care nimeni nu avea voie să îl atingă. Douăzeci de oameni, douăzeci de calculatoare, o liniște ca la bibliotecă. Colegul din stânga mea, Vali, lucra acolo de unsprezece ani. Într-o zi mi-a spus, fără să ridice ochii de pe ecran, că plafonul are patru sute optzeci și șase de plăci. Le numărase. De două ori, ca să fie sigur.\n\nAm râs atunci. Mi-au trebuit încă trei ani ca să înțeleg că nu fusese o glumă, ci un diagnostic.\n\nMunca în sine nu era grea. Verificam proiecte, calculam structuri, semnam hârtii. Făceam totul corect și nu mă bucura nimic. Cel mai rău nu era plictiseala, ci gândul că aș putea continua așa treizeci de ani și nimeni nu ar observa vreo diferență dacă în locul meu ar sta altcineva.\n\nSchimbarea a venit dintr-un accident. O verișoară care preda matematică m-a rugat să o înlocuiesc două săptămâni la un liceu de la marginea orașului. Nu voiam deloc. M-am dus pentru că nu am știut cum să spun nu.\n\nPrima oră a fost un dezastru. Am vorbit patruzeci de minute despre forțe și echilibru, iar ei se uitau la mine cum te uiți la o știre despre o țară foarte îndepărtată. La final, o fată din ultima bancă a ridicat mâna și m-a întrebat de ce o clădire înaltă nu cade atunci când bate vântul tare.\n\nÎntrebarea nu era în programă. I-am răspuns douăzeci de minute, cu desene urâte pe tablă, iar clasa a tăcut altfel decât tăcuse până atunci. Nu din politețe. Din curiozitate.\n\nÎn seara aceea m-am întors acasă și nu am putut să dorm. Nu de nervi, ci de entuziasm — un sentiment pe care nu îl mai avusesem de ani de zile și pe care aproape că nu l-am recunoscut.\n\nMi-au trebuit apoi doi ani ca să fac pasul. Am dat un examen, am urmat un modul pedagogic și am pierdut aproape jumătate din salariu. Tata nu a spus nimic timp de o lună. Apoi m-a întrebat, la telefon, dacă nu cumva este o criză trecătoare. I-am răspuns că sper să nu fie.\n\nAstăzi predau fizică la un liceu obișnuit. Nu este o poveste romantică. Am treizeci de ore pe săptămână, corectez teze duminica și există elevi care nu vor deschide niciodată manualul, oricât m-aș strădui. Salariul a rămas mai mic decât înainte. Colegii care au rămas în construcții și-au luat între timp case.\n\nDar există dimineți în care explic același lucru pentru a zecea oară, cu alte cuvinte, și văd pe fața cuiva momentul exact în care totul se așază la locul lui. Este o schimbare foarte mică. Dacă nu te uiți atent, o ratezi.\n\nNu spun că toată lumea ar trebui să își schimbe meseria. Cunosc destui oameni care au plecat spre ceva presupus mai frumos și au ajuns doar în alt birou, cu alte ferestre care nu se deschid.\n\nSpun doar că merită să observi ce faci în ziua în care nimeni nu te obligă la nimic. Eu, în duminicile libere, citeam despre poduri și le explicam prietenilor cum stau în picioare. Mi-au trebuit zece ani ca să înțeleg ce înseamnă asta.\n\nVali, apropo, mai lucrează acolo. Anul trecut m-am întâlnit cu el pe stradă. Mi-a spus, mulțumit, că au schimbat plafonul.",
  en:"At twenty-two I thought I knew exactly what I wanted. I had finished civil engineering, I had a handsome diploma in a plastic folder and a father who showed it to the neighbours. \"Engineer,\" he would say, leaning on every syllable, as though it were a noble title. The first office I worked in had windows that did not open and an air conditioning unit nobody was allowed to touch. Twenty people, twenty computers, a silence like a library's. The colleague to my left, Vali, had worked there for eleven years. One day he told me, without lifting his eyes from the screen, that the ceiling had four hundred and eighty-six tiles. He had counted them. Twice, to be sure. I laughed at the time. It took me another three years to understand that it had not been a joke but a diagnosis. The work itself was not hard. I checked designs, calculated structures, signed papers. I did everything correctly and none of it gave me any pleasure. The worst part was not the boredom but the thought that I could carry on like that for thirty years and nobody would notice any difference if somebody else sat in my place. The change came out of an accident. A cousin who taught maths asked me to stand in for her for two weeks at a secondary school on the edge of the city. I did not want to at all. I went because I did not know how to say no. The first lesson was a disaster. I talked for forty minutes about forces and equilibrium, and they looked at me the way you look at a news item about a very distant country. At the end, a girl in the back row put up her hand and asked me why a tall building does not fall over when the wind blows hard. The question was not on the syllabus. I answered it for twenty minutes, with ugly drawings on the board, and the class went quiet in a different way than it had been quiet before. Not out of politeness. Out of curiosity. That evening I went home and could not sleep. Not from nerves, but from excitement — a feeling I had not had in years and which I almost failed to recognise. It then took me two years to make the move. I sat an exam, took a teacher-training module and lost nearly half my salary. My father said nothing for a month. Then he asked me, on the phone, whether it might not be a passing crisis. I told him I hoped it was not. Today I teach physics at an ordinary secondary school. It is not a romantic story. I have thirty hours a week, I mark papers on Sundays, and there are pupils who will never open the textbook however hard I try. The salary has stayed lower than before. The colleagues who stayed in construction have bought houses in the meantime. But there are mornings when I explain the same thing for the tenth time, in different words, and I see on somebody's face the exact moment when it all falls into place. It is a very small change. If you are not watching closely, you miss it. I am not saying everyone should change career. I know plenty of people who left for something supposedly finer and ended up only in another office, with other windows that do not open. I am only saying it is worth noticing what you do on the day nobody obliges you to do anything. On my free Sundays I read about bridges and explained to my friends how they stay up. It took me ten years to understand what that meant. Vali, by the way, still works there. Last year I ran into him in the street. He told me, with satisfaction, that they had replaced the ceiling.",
  glossary:{"dosar":"folder, file","apăsând":"pressing, leaning on","silabă":"syllable","titlu nobiliar":"noble title","plafonul":"the ceiling","plăci":"tiles, panels","le numărase":"he had counted them","diagnostic":"diagnosis","plictiseala":"the boredom","în locul meu":"in my place","verișoară":"cousin (female)","să o înlocuiesc":"to stand in for her","de la marginea":"on the edge of","dezastru":"disaster","echilibru":"equilibrium, balance","îndepărtată":"distant, far-off","ultima bancă":"the back row (desk)","programă":"syllabus","tablă":"blackboard","din politețe":"out of politeness","curiozitate":"curiosity","entuziasm":"excitement, enthusiasm","nu îl mai avusesem":"I had not had it (for a long time)","să fac pasul":"to take the step","modul pedagogic":"teacher-training module","trecătoare":"passing, temporary","corectez teze":"I mark papers","oricât m-aș strădui":"however hard I try","între timp":"in the meantime","se așază la locul lui":"falls into place","o ratezi":"you miss it","presupus":"supposedly","nu te obligă":"does not oblige you","poduri":"bridges","stau în picioare":"stay standing","apropo":"by the way","mulțumit":"satisfied, pleased"}},
 {id:"r_b1_long_somn", title:"De ce dormim prost", titleEn:"Why we sleep badly", level:"b1_2", format:"opinion essay", wordCount:561,
  ro:"Este unu și patruzeci noaptea și fac un calcul pe care îl cunoaște toată lumea. Dacă adorm acum, în cinci minute, îmi ies șase ore și douăzeci de minute. Dacă adorm în zece, șase și un sfert. Calculul acesta nu m-a ajutat niciodată să adorm. L-am făcut, totuși, de câteva mii de ori.\n\nCu o oră înainte îmi spusesem că mai verific un singur lucru pe telefon. Este cea mai veche minciună pe care ne-o spunem, imediat după „mă odihnesc cinci minute”.\n\nStatisticile arată că românii dorm, în medie, cu aproape o oră mai puțin decât acum patruzeci de ani. La fel se întâmplă aproape peste tot în Europa. Explicația obișnuită este telefonul, iar telefonul chiar are partea lui de vină: lumina albastră a ecranului întârzie producția de melatonină, hormonul care îi spune creierului că s-a făcut seară.\n\nDar dacă ar fi doar lumina, soluția ar fi simplă și problema s-ar fi rezolvat demult. Există aplicații care fac ecranul galben după ora zece. Le folosim. Și tot nu dormim.\n\nCeva mult mai interesant apare atunci când te uiți la istorie. Până în secolul al nouăsprezecelea, în multe părți ale Europei oamenii nu dormeau opt ore la rând. Dormeau patru ore, se trezeau pe la miezul nopții pentru o oră sau două — vorbeau, se rugau, se vizitau între ei — și apoi dormeau din nou până dimineața. Documentele vremii numesc aceste perioade „primul somn” și „al doilea somn”, fără nicio urmă de îngrijorare. Nimeni nu credea că are o problemă.\n\nCeea ce înseamnă că o parte din suferința noastră modernă vine dintr-o așteptare, nu dintr-o boală. Ne trezim la trei dimineața, constatăm că nu dormim „cum trebuie” și ne speriem. Frica, la rândul ei, ne ține treji.\n\nAici industria somnului a reușit să facă lucrurile mai rele înainte de a le face mai bune. Avem acum ceasuri care ne dau, dimineața, o notă pentru noaptea trecută. Cunosc oameni care se trezesc odihniți, își văd scorul de patruzeci și trei la sută și se simt brusc obosiți. Există chiar un termen pentru asta: ortosomnie, anxietatea provocată de măsurarea propriului somn.\n\nTotuși, explicația care mi se pare cea mai onestă nu ține nici de lumină, nici de tehnologie.\n\nMulți oameni nu se culcă târziu pentru că nu le este somn. Se culcă târziu pentru că ziua nu le-a aparținut. Serviciul, drumul, copiii, cumpărăturile, telefoanele care trebuie date. Noaptea este primul moment în care nimeni nu le cere nimic. Renunți greu la ea, chiar știind foarte bine că vei plăti dimineața.\n\nPsihologii au și un nume pentru acest comportament: amânarea răzbunătoare a orei de culcare. Numele sună caraghios, dar descrie exact ce se întâmplă. Nu este lipsă de disciplină. Este singurul mod în care unii oameni mai recuperează ceva din propria zi.\n\nDacă lucrurile stau așa, atunci sfaturile obișnuite ratează ținta. „Culcă-te la aceeași oră”, „nu bea cafea după prânz”, „scoate telefonul din dormitor” — toate sunt corecte și niciunul nu răspunde la întrebarea adevărată, care este: unde altundeva, în ziua ta, ai o oră care să fie a ta?\n\nNu am o soluție elegantă. Știu doar că, în lunile în care am avut ceva timp liber înainte de ora zece seara, m-am culcat mai devreme fără efort și fără să îmi propun.\n\nIar în celelalte luni am stat treaz până la unu și patruzeci, făcând calcule.",
  en:"It is one forty in the morning and I am doing a calculation everybody knows. If I fall asleep now, in five minutes, that gives me six hours and twenty minutes. If I fall asleep in ten, six and a quarter. This calculation has never once helped me fall asleep. I have done it, all the same, a few thousand times. An hour earlier I had told myself I would check just one more thing on my phone. It is the oldest lie we tell ourselves, right after \"I'll rest for five minutes.\" The statistics show that Romanians sleep, on average, almost an hour less than they did forty years ago. Much the same is happening nearly everywhere in Europe. The usual explanation is the phone, and the phone does have its share of the blame: the blue light of the screen delays the production of melatonin, the hormone that tells the brain evening has come. But if it were only the light, the solution would be simple and the problem would have been solved long ago. There are apps that turn the screen yellow after ten o'clock. We use them. And still we do not sleep. Something far more interesting emerges when you look at history. Until the nineteenth century, in many parts of Europe people did not sleep eight hours at a stretch. They slept four hours, woke around midnight for an hour or two — they talked, they prayed, they visited one another — and then slept again until morning. Documents of the period call these stretches \"first sleep\" and \"second sleep\", without a trace of concern. Nobody believed they had a problem. Which means that part of our modern suffering comes from an expectation, not from an illness. We wake at three in the morning, note that we are not sleeping \"properly\" and take fright. The fear, in its turn, keeps us awake. Here the sleep industry has managed to make things worse before making them better. We now have watches that give us, in the morning, a mark for the night before. I know people who wake up rested, see their score of forty-three per cent and suddenly feel tired. There is even a term for it: orthosomnia, the anxiety produced by measuring your own sleep. Still, the explanation that seems most honest to me has nothing to do with light or with technology. Many people do not go to bed late because they are not sleepy. They go to bed late because the day did not belong to them. Work, the commute, the children, the shopping, the phone calls that have to be made. Night is the first moment when nobody is asking them for anything. You give it up reluctantly, even knowing perfectly well that you will pay in the morning. Psychologists even have a name for this behaviour: revenge bedtime procrastination. The name sounds ridiculous, but it describes exactly what happens. It is not a lack of discipline. It is the only way some people still recover something of their own day. If that is how things stand, then the usual advice misses the target. \"Go to bed at the same time\", \"don't drink coffee after lunch\", \"take the phone out of the bedroom\" — all of them are correct and not one of them answers the real question, which is: where else, in your day, do you have an hour that is yours? I have no elegant solution. I know only that in the months when I had some free time before ten in the evening, I went to bed earlier without effort and without setting out to. And in the other months I stayed awake until one forty, doing calculations.",
  glossary:{"adorm":"I fall asleep","îmi ies":"it works out to, I get","un sfert":"a quarter","minciună":"lie","mă odihnesc":"I rest","în medie":"on average","partea lui de vină":"its share of the blame","lumina albastră":"blue light","întârzie":"delays","melatonină":"melatonin","creierului":"to the brain","s-a făcut seară":"evening has come","demult":"long ago","ecranul":"the screen","tot nu":"still not","la rând":"at a stretch, in a row","miezul nopții":"midnight","se rugau":"they prayed","se vizitau":"they visited one another","documentele vremii":"the documents of the period","nicio urmă":"not a trace","îngrijorare":"concern, worry","suferința":"the suffering","așteptare":"expectation","constatăm":"we note, we observe","ne speriem":"we take fright","la rândul ei":"in its turn","treji":"awake (pl.)","o notă":"a mark, a grade","odihniți":"rested","scorul":"the score","brusc":"suddenly","anxietatea":"the anxiety","provocată":"caused, produced","propriului somn":"of your own sleep","nu ține de":"has nothing to do with","nu le este somn":"they are not sleepy","nu le-a aparținut":"did not belong to them","drumul":"the commute, the journey","renunți greu":"you give it up reluctantly","amânarea":"the postponement","răzbunătoare":"vengeful","ora de culcare":"bedtime","caraghios":"ridiculous, funny","lipsă de disciplină":"lack of discipline","recuperează":"recovers, salvages","ratează ținta":"miss the target","altundeva":"elsewhere","fără să îmi propun":"without setting out to","treaz":"awake"}},
 {id:"r_b1_long_sat", title:"Satul care s-a golit", titleEn:"The village that emptied", level:"b1_2", format:"reportage", wordCount:658,
  ro:"Drumul până la Poiana Mare se termină cu unsprezece kilometri de asfalt spart. Șoferul microbuzului, singurul care mai vine aici, conduce încet și povestește. Acum treizeci de ani făcea cursa de patru ori pe zi și urca lumea în picioare. Astăzi vine marțea și vinerea, iar dacă are cinci pasageri e o zi bună.\n\nÎn anii optzeci, în sat locuiau aproape o mie două sute de oameni. La ultimul recensământ au fost numărați o sută nouăzeci și patru. Vârsta medie trece de șaizeci și cinci de ani.\n\nPrimarul, domnul Ionescu, are șaizeci și doi de ani și conduce comuna de nouăsprezece. Ne arată școala. Este curată, are geamuri noi, are chiar și o tablă interactivă cumpărată dintr-un proiect european. Are și căldură iarna. Nu are elevi. Ultimii patru au fost mutați acum trei ani la școala din comuna vecină, la douăzeci și doi de kilometri.\n\n„Nu o închid”, spune el, când îl întreb de ce încălzește o clădire goală. Ridică din umeri și se uită în altă parte. „Dacă o închid, gata. Atât timp cât are căldură, mai poate veni cineva.”\n\nMagazinul se deschide la ora nouă și se închide la zece și jumătate. Doamna Viorica, care îl ține de douăzeci și opt de ani, spune că nu are rost să stea mai mult. Vinde pâine, ulei, zahăr, țigări și, în cantități surprinzătoare, cafea. Cunoaște toți clienții pe nume și știe ce cumpără fiecare înainte să intre pe ușă.\n\nPovestea de aici seamănă cu multe altele. Tinerii au plecat întâi la oraș, apoi în străinătate. Italia și Spania, mai ales, apoi Germania. Trimit bani acasă — case noi, mari, cu geamuri termopan și garduri frumoase, în care nu locuiește nimeni unsprezece luni pe an. În august satul are mașini cu numere străine pe fiecare uliță și seamănă, pentru două săptămâni, cu ce a fost.\n\nDoamna Maria s-a întors definitiv anul trecut, după paisprezece ani de îngrijit bătrâni lângă Torino. Are casa cea mai frumoasă de pe uliță și, spune ea, cea mai tăcută. Fiul ei a rămas acolo, s-a căsătorit cu o italiancă și are doi copii care înțeleg românește, dar răspund în italiană.\n\n„Am muncit paisprezece ani ca să îmi fac casă aici”, spune ea. „Acum stau în ea singură și nu am cu cine să vorbesc peste gard. Nu regret. Dar nu asta am plănuit.”\n\nNu toți au plecat. Familia Dobre s-a mutat aici acum șase ani, din Craiova. Au cumpărat o casă veche cu treizeci de mii de euro, au reparat-o singuri și cresc oi. El lucrează și de acasă, la calculator, pentru o firmă din Belgia; internetul, spune el râzând, este mai bun decât la bloc. Au doi copii, care fac naveta la școala din comuna vecină.\n\nSunt singura familie cu copii din sat. Domnul Ionescu îi pomenește de trei ori în discuția noastră de o oră.\n\nCe se pierde când dispare un sat nu este doar populația. Sunt cunoștințe practice care nu se scriu nicăieri: cum se altoiește un pom, când se seamănă, ce se face cu un vițel bolnav la trei noaptea când veterinarul e la patruzeci de kilometri. Sunt cuvinte care există doar aici și pe care dicționarele nu le-au prins niciodată.\n\nExistă și un alt fel de a privi lucrurile, pe care primarul îl acceptă fără plăcere. Oamenii nu au plecat pentru că au fost alungați. Au plecat pentru că altundeva se trăia mai bine, iar copiii lor au acum lucruri pe care ei nu le-au avut niciodată. A cere cuiva să rămână într-un loc greu, ca locul să nu dispară, este ușor de spus și greu de justificat.\n\nLa plecare, șoferul microbuzului îmi spune că anul viitor poate se reduce cursa la o zi pe săptămână. Nu pare supărat. Spune doar că, dacă se întâmplă, doamna Viorica va trebui să își aducă marfa singură.\n\nDomnul Ionescu rămâne în poartă până nu ne mai vede. Școala, în spatele lui, are toate geamurile întregi.",
  en:"The road to Poiana Mare ends with eleven kilometres of broken asphalt. The driver of the minibus, the only one that still comes here, drives slowly and talks. Thirty years ago he made the run four times a day and people stood in the aisle. Today he comes on Tuesdays and Fridays, and if he has five passengers it is a good day. In the eighties, nearly one thousand two hundred people lived in the village. At the last census a hundred and ninety-four were counted. The average age is over sixty-five. The mayor, Mr Ionescu, is sixty-two and has run the commune for nineteen years. He shows us the school. It is clean, it has new windows, it even has an interactive whiteboard bought through a European project. It has heating in winter too. It has no pupils. The last four were moved three years ago to the school in the neighbouring commune, twenty-two kilometres away. \"I am not closing it,\" he says, when I ask why he heats an empty building. He shrugs and looks away. \"If I close it, that's the end. As long as it has heating, somebody might still come.\" The shop opens at nine and closes at half past ten. Mrs Viorica, who has kept it for twenty-eight years, says there is no point staying longer. She sells bread, oil, sugar, cigarettes and, in surprising quantities, coffee. She knows all her customers by name and knows what each of them buys before they come through the door. The story here resembles many others. The young left first for the city, then abroad. Italy and Spain above all, then Germany. They send money home — new houses, large ones, with double glazing and handsome fences, in which nobody lives for eleven months of the year. In August the village has cars with foreign plates on every lane and looks, for two weeks, like what it used to be. Mrs Maria came back for good last year, after fourteen years caring for the elderly near Turin. She has the finest house on the lane and, she says, the quietest. Her son stayed there, married an Italian woman, and has two children who understand Romanian but answer in Italian. \"I worked fourteen years to build myself a house here,\" she says. \"Now I live in it alone and I have nobody to talk to over the fence. I do not regret it. But this is not what I planned.\" Not everyone left. The Dobre family moved here six years ago from Craiova. They bought an old house for thirty thousand euros, repaired it themselves, and keep sheep. He also works from home, at the computer, for a firm in Belgium; the internet, he says laughing, is better than it was in the flat. They have two children, who commute to the school in the neighbouring commune. They are the only family with children in the village. Mr Ionescu mentions them three times in our hour-long conversation. What is lost when a village disappears is not only the population. There is practical knowledge written down nowhere: how to graft a fruit tree, when to sow, what to do with a sick calf at three in the morning when the vet is forty kilometres away. There are words that exist only here and that the dictionaries never caught. There is another way of looking at it, too, which the mayor accepts without pleasure. People did not leave because they were driven out. They left because life was better elsewhere, and their children now have things they themselves never had. To ask somebody to stay in a hard place so that the place does not disappear is easy to say and hard to justify. As I leave, the minibus driver tells me that next year the service may be cut to one day a week. He does not seem upset. He only says that if it happens, Mrs Viorica will have to bring her stock in herself. Mr Ionescu stays at the gate until he can no longer see us. Behind him, the school has every one of its windows intact.",
  glossary:{"asfalt spart":"broken asphalt","microbuzului":"of the minibus","cursa":"the run, the service","urca lumea în picioare":"people stood (rode standing)","recensământ":"census","vârsta medie":"average age","primarul":"the mayor","comuna":"the commune (rural administrative unit)","tablă interactivă":"interactive whiteboard","căldură":"heating, warmth","elevi":"pupils","comuna vecină":"the neighbouring commune","încălzește":"heats","ridică din umeri":"shrugs","gata":"that is the end of it","atât timp cât":"as long as","nu are rost":"there is no point","cantități":"quantities","pe nume":"by name","în străinătate":"abroad","geamuri termopan":"double glazing","garduri":"fences","numere străine":"foreign number plates","uliță":"village lane","definitiv":"for good, permanently","de îngrijit bătrâni":"caring for the elderly","tăcută":"quiet, silent","s-a căsătorit":"he married","peste gard":"over the fence","nu regret":"I do not regret it","am plănuit":"I planned","cresc oi":"they keep sheep","la bloc":"in the block of flats","fac naveta":"they commute","pomenește":"mentions","cunoștințe practice":"practical knowledge","se altoiește":"is grafted","pom":"fruit tree","se seamănă":"one sows","vițel":"calf","veterinarul":"the vet","nu le-au prins":"never caught them","fără plăcere":"without pleasure","alungați":"driven out","altundeva":"elsewhere","greu de justificat":"hard to justify","se reduce":"is cut, is reduced","marfa":"the stock, the goods","în poartă":"at the gate","întregi":"intact, unbroken"}}
];
